#[tokio::test]
async fn native_local_response_objects_expose_bounded_constructors_and_identity() {
    let config = NativeEngineConfig::default()
        .with_fixture("fixture://response-objects", "<p>Responses</p>")
        .unwrap()
        .with_initial_url("fixture://response-objects");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            r#"(async () => {
                const constructed = new Response(new Uint8Array([0, 255, 128, 65]), {
                    status: 201,
                    statusText: 'Created',
                    headers: { 'Content-Type': 'application/octet-stream' },
                });
                const json = Response.json({ ready: true });
                const empty = new Response();
                const error = Response.error();
                const redirect = Response.redirect('https://example.test/next', 307);
                const clone = constructed.clone();
                let headerMutation;
                try { constructed.headers.set('x-test', 'blocked'); } catch (error) { headerMutation = [error.name, error.message]; }
                globalThis.responseObjects = [
                    constructed instanceof Response,
                    constructed.headers instanceof Headers,
                    constructed.status,
                    constructed.statusText,
                    constructed.headers.get('content-type'),
                    headerMutation,
                    Array.from(await constructed.bytes()),
                    await json.text(),
                    json.headers.get('content-type'),
                    empty.body === null,
                    error.type,
                    error.status,
                    error.body === null,
                    redirect.status,
                    redirect.headers.get('location'),
                    redirect.body === null,
                    clone !== constructed,
                    Array.from(await clone.bytes()),
                ];
            })()"#,
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.responseObjects")
            .await
            .unwrap(),
        serde_json::json!([
            true,
            true,
            201,
            "Created",
            "application/octet-stream",
            ["TypeError", "native response Headers are immutable"],
            [0, 255, 128, 65],
            "{\"ready\":true}",
            "application/json",
            true,
            "error",
            0,
            true,
            307,
            "https://example.test/next",
            true,
            true,
            [0, 255, 128, 65],
        ])
    );
    engine.close_async().await.unwrap();
}

#[tokio::test]
async fn native_local_response_objects_support_stream_bodies_and_tee() {
    let config = NativeEngineConfig::default()
        .with_fixture("fixture://response-streams", "<p>Response streams</p>")
        .unwrap()
        .with_initial_url("fixture://response-streams");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            r#"(async () => {
                const makeStream = () => new ReadableStream({
                    start(controller) {
                        controller.enqueue('response-');
                        controller.enqueue('body');
                        controller.close();
                    },
                });
                const input = makeStream();
                const response = new Response(input, { headers: { 'Content-Type': 'text/plain' } });
                const sameBody = response.body === input;
                const clone = response.clone();
                const initial = [response.bodyUsed, clone.bodyUsed];
                const text = await response.text();
                const cloneText = await clone.text();
                const after = [response.bodyUsed, clone.bodyUsed];
                const responseAgain = await response.text().then(() => 'readable', error => error.name);
                const cloneAgain = await clone.text().then(() => 'readable', error => error.name);
                const lockedInput = makeStream();
                const lockedReader = lockedInput.getReader();
                const lockedResponse = (() => {
                    try { new Response(lockedInput); return 'constructable'; }
                    catch (error) { return error.name; }
                })();
                lockedReader.releaseLock();
                globalThis.responseStreamObjects = [
                    sameBody,
                    initial,
                    text,
                    cloneText,
                    after,
                    responseAgain,
                    cloneAgain,
                    lockedResponse,
                ];
            })()"#,
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.responseStreamObjects")
            .await
            .unwrap(),
        serde_json::json!([
            true,
            [false, false],
            "response-body",
            "response-body",
            [true, true],
            "TypeError",
            "TypeError",
            "TypeError",
        ])
    );
    engine.close_async().await.unwrap();
}

#[tokio::test]
async fn native_local_streams_pipe_to_bounded_writable_sinks() {
    let config = NativeEngineConfig::default()
        .with_fixture("fixture://stream-piping", "<p>Stream piping</p>")
        .unwrap()
        .with_initial_url("fixture://stream-piping");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            r#"(async () => {
                const events = [];
                const sink = new WritableStream({
                    write(value) { events.push('write:' + value); },
                    close() { events.push('close'); },
                });
                const source = new ReadableStream({
                    start(controller) {
                        controller.enqueue('one');
                        controller.enqueue('two');
                        controller.close();
                    },
                });
                await source.pipeTo(sink);
                const writer = sink.getWriter();
                const writerClosed = writer.closed.then(() => 'resolved', error => 'rejected:' + error.name);
                const afterPipe = [source.locked, sink.locked, writer.desiredSize];
                await writerClosed;
                writer.releaseLock();
                const failureEvents = [];
                const failingSource = new ReadableStream({
                    start(controller) { controller.enqueue('bad'); },
                    cancel(reason) { failureEvents.push('cancel:' + reason.message); },
                });
                const failingSink = new WritableStream({
                    write() { throw new Error('sink-failure'); },
                    abort(reason) { failureEvents.push('abort:' + reason.message); },
                });
                const failure = await failingSource.pipeTo(failingSink).then(() => 'resolved', error => error.message);
                globalThis.streamPipeResult = {
                    events,
                    afterPipe,
                    writerClosed: await writerClosed,
                    failure,
                    failureEvents,
                    failingSourceLocked: failingSource.locked,
                    failingSinkLocked: failingSink.locked,
                };
            })()"#,
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.streamPipeResult")
            .await
            .unwrap(),
        serde_json::json!({
            "events": ["write:one", "write:two", "close"],
            "afterPipe": [false, true, null],
            "writerClosed": "resolved",
            "failure": "sink-failure",
            "failureEvents": ["abort:sink-failure", "cancel:sink-failure"],
            "failingSourceLocked": false,
            "failingSinkLocked": false
        })
    );
    engine.close_async().await.unwrap();
}

#[tokio::test]
async fn native_local_transform_streams_process_pipe_through_values() {
    let config = NativeEngineConfig::default()
        .with_fixture("fixture://transform-streams", "<p>Transform streams</p>")
        .unwrap()
        .with_initial_url("fixture://transform-streams");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            r#"(async () => {
                const events = [];
                const transform = new TransformStream({
                    start() { events.push('start'); },
                    transform(value, controller) {
                        events.push('transform:' + value);
                        controller.enqueue(value.toUpperCase());
                    },
                    flush(controller) {
                        events.push('flush');
                        controller.enqueue('tail');
                    },
                });
                const source = new ReadableStream({
                    start(controller) {
                        controller.enqueue('one');
                        controller.enqueue('two');
                        controller.close();
                    },
                });
                const output = source.pipeThrough(transform);
                const reader = output.getReader();
                const first = await reader.read();
                const second = await reader.read();
                const tail = await reader.read();
                const end = await reader.read();
                reader.releaseLock();
                globalThis.transformStreamResult = {
                    events,
                    values: [first.value, second.value, tail.value, end.done],
                    identities: [output === transform.readable, transform.writable instanceof WritableStream, output instanceof ReadableStream],
                    sourceLocked: source.locked,
                    outputLocked: output.locked,
                };
            })()"#,
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.transformStreamResult")
            .await
            .unwrap(),
        serde_json::json!({
            "events": ["start", "transform:one", "transform:two", "flush"],
            "values": ["ONE", "TWO", "tail", true],
            "identities": [true, true, true],
            "sourceLocked": false,
            "outputLocked": false
        })
    );
    engine.close_async().await.unwrap();
}

#[tokio::test]
async fn native_local_byte_streams_support_byob_reads_and_strategies() {
    let config = NativeEngineConfig::default()
        .with_fixture("fixture://byte-streams", "<p>Byte streams</p>")
        .unwrap()
        .with_initial_url("fixture://byte-streams");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            r#"(async () => {
                const events = [];
                const source = new ReadableStream({
                    type: 'bytes',
                    pull(controller) {
                        const request = controller.byobRequest;
                        events.push(request ? ['byob', request.view.byteLength, controller.desiredSize] : ['default', controller.desiredSize]);
                        if (!request) throw new Error('BYOB request was not supplied');
                        request.view[0] = 9;
                        request.view[1] = 8;
                        request.respond(2);
                        controller.close();
                    },
                }, { highWaterMark: 2, size(chunk) { return chunk.byteLength; } });
                const reader = source.getReader({ mode: 'byob' });
                const view = new Uint8Array(4);
                const first = await reader.read(view);
                const end = await reader.read(new Uint8Array(2));
                reader.releaseLock();

                let strategyDesiredSize;
                const queued = new ReadableStream({
                    type: 'bytes',
                    start(controller) {
                        controller.enqueue(new Uint8Array([1, 2, 3]));
                        strategyDesiredSize = controller.desiredSize;
                        controller.close();
                    },
                }, { highWaterMark: 2, size(chunk) { return chunk.byteLength; } });
                const queuedReader = queued.getReader({ mode: 'byob' });
                const queuedFirst = await queuedReader.read(new Uint8Array(2));
                const queuedSecond = await queuedReader.read(new Uint8Array(2));
                const queuedEnd = await queuedReader.read(new Uint8Array(2));
                queuedReader.releaseLock();
                const replacement = new ReadableStream({
                    type: 'bytes',
                    pull(controller) {
                        controller.byobRequest.respondWithNewView(new Uint8Array([7, 6]));
                        controller.close();
                    },
                });
                const replacementReader = replacement.getReader({ mode: 'byob' });
                const replacementResult = await replacementReader.read(new Uint8Array(2));
                replacementReader.releaseLock();
                const invalid = (() => {
                    try { new ReadableStream().getReader({ mode: 'byob' }); return 'accepted'; }
                    catch (error) { return error.name; }
                })();
                globalThis.byobResult = {
                    events,
                    first: [Array.from(first.value), first.value.byteLength, first.done],
                    end: [end.value.byteLength, end.done],
                    queued: [Array.from(queuedFirst.value), Array.from(queuedSecond.value), [queuedEnd.value.byteLength, queuedEnd.done]],
                    replacement: [Array.from(replacementResult.value), replacementResult.done],
                    desiredSize: strategyDesiredSize,
                    invalid,
                };
            })()"#,
        )
        .await
        .unwrap();
    let result = engine
        .evaluate_async("globalThis.byobResult")
        .await
        .unwrap();
    assert_eq!(
        result,
        serde_json::json!({
            "events": [["byob", 4, 2]],
            "first": [[9, 8], 2, false],
            "end": [0, true],
            "queued": [[1, 2], [3], [0, true]],
            "replacement": [[7, 6], false],
            "desiredSize": -1,
            "invalid": "TypeError"
        })
    );
    engine.close_async().await.unwrap();
}

#[tokio::test]
async fn native_local_script_applies_bounded_dom_commands_once() {
    let config = NativeEngineConfig::default()
        .with_fixture(
            "fixture://script-commands",
            "<input id='name' type='text'><input id='toggle' type='checkbox'><select id='choice'><option id='one' value='one'>One</option><option id='two' value='two'>Two</option></select><select id='many' multiple><option id='many-one' value='one' selected>One</option><option id='many-two' value='two'>Two</option></select>",
        )
        .unwrap()
        .with_initial_url("fixture://script-commands");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();
    let initial_revision = engine.revision();

    let value = engine
        .evaluate_async(
            "(() => { const input = document.getElementById('name'); input.value = 'local-value'; input.setAttribute('data-source', 'script'); return input.value; })()",
        )
        .await
        .unwrap();
    assert_eq!(value, serde_json::json!("local-value"));
    assert_eq!(engine.revision(), initial_revision + 1);
    assert_eq!(
        engine
            .evaluate_async("document.getElementById('name').getAttribute('data-source')")
            .await
            .unwrap(),
        serde_json::json!("script")
    );
    assert_eq!(engine.revision(), initial_revision + 1);

    let checked = engine
        .evaluate_async(
            "(() => { const toggle = document.getElementById('toggle'); toggle.click(); return toggle.checked; })()",
        )
        .await
        .unwrap();
    assert_eq!(checked, serde_json::json!(true));
    assert_eq!(engine.revision(), initial_revision + 2);

    let state = engine
        .evaluate_async(
            "(() => { const toggle = document.getElementById('toggle'); const input = document.getElementById('name'); toggle.checked = false; input.removeAttribute('data-source'); return { checked: toggle.checked, source: input.getAttribute('data-source') }; })()",
        )
        .await
        .unwrap();
    assert_eq!(
        state,
        serde_json::json!({
            "checked": false,
            "source": null,
        })
    );
    assert_eq!(engine.revision(), initial_revision + 3);

    assert_eq!(
        engine
            .evaluate_async("(() => { const option = document.getElementById('two'); option.selected = true; return option.selected; })()")
            .await
            .unwrap(),
        serde_json::json!(true)
    );
    assert_eq!(engine.revision(), initial_revision + 4);
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const select = document.getElementById('many'); select.options[1].selected = true; return { multiple: select.multiple, options: select.options.map(option => option.selected), selected: select.selectedOptions.map(option => option.value) }; })()",
            )
            .await
            .unwrap(),
        serde_json::json!({
            "multiple": true,
            "options": [true, true],
            "selected": ["one", "two"],
        })
    );
    engine.close_async().await.unwrap();
}

#[tokio::test]
async fn native_local_script_owns_event_listeners_and_focus_order() {
    let config = NativeEngineConfig::default()
        .with_fixture(
            "fixture://script-events",
            "<div id='outer'><section id='middle'><input id='toggle' type='checkbox'></section></div><input id='name' type='text'>",
        )
        .unwrap()
        .with_initial_url("fixture://script-events");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();
    let initial_revision = engine.revision();

    let registered = engine
        .evaluate_async(
            "(() => { const toggle = document.getElementById('toggle'); const outer = document.getElementById('outer'); const middle = document.getElementById('middle'); globalThis.events = []; globalThis.onOuterCapture = (event) => { globalThis.events.push('capture:' + event.currentTarget.id + ':' + event.eventPhase); }; globalThis.onMiddleCapture = (event) => { globalThis.events.push('capture:' + event.currentTarget.id + ':' + event.eventPhase); }; globalThis.onOuterBubble = (event) => { globalThis.events.push('bubble:' + event.currentTarget.id + ':' + event.eventPhase); }; globalThis.onToggleClick = (event) => { globalThis.events.push(event.type + ':' + event.target.id + ':' + event.currentTarget.id); document.getElementById('name').value = 'from-listener'; event.preventDefault(); }; globalThis.onProbe = (event) => { globalThis.events.push(event.type + ':' + event.detail); }; outer.addEventListener('click', globalThis.onOuterCapture, true); middle.addEventListener('click', globalThis.onMiddleCapture, { capture: true }); outer.addEventListener('click', globalThis.onOuterBubble); toggle.addEventListener('click', globalThis.onToggleClick); toggle.addEventListener('probe', globalThis.onProbe); toggle.focus(); const accepted = toggle.dispatchEvent(new CustomEvent('probe', { cancelable: true, detail: 'detail' })); return { active: document.activeElement.id, accepted, eventType: new Event('probe').type, parent: toggle.parentElement.id, events: globalThis.events }; })()",
        )
        .await
        .unwrap();
    assert_eq!(
        registered,
        serde_json::json!({
            "active": "toggle",
            "accepted": true,
            "eventType": "probe",
            "parent": "middle",
            "events": ["probe:detail"],
        })
    );
    assert_eq!(engine.revision(), initial_revision + 1);

    let prevented = engine
        .evaluate_async(
            "(() => { const toggle = document.getElementById('toggle'); return { checked: (toggle.click(), toggle.checked), value: document.getElementById('name').value, events: globalThis.events }; })()",
        )
        .await
        .unwrap();
    assert_eq!(
        prevented,
        serde_json::json!({
            "checked": false,
            "value": "from-listener",
            "events": [
                "probe:detail",
                "capture:outer:1",
                "capture:middle:1",
                "click:toggle:toggle",
                "bubble:outer:3",
            ],
        })
    );
    assert_eq!(engine.revision(), initial_revision + 2);

    let accepted = engine
        .evaluate_async(
            "(() => { const toggle = document.getElementById('toggle'); toggle.removeEventListener('click', globalThis.onToggleClick); toggle.click(); return toggle.checked; })()",
        )
        .await
        .unwrap();
    assert_eq!(accepted, serde_json::json!(true));
    assert_eq!(engine.revision(), initial_revision + 3);

    let focus = engine
        .evaluate_async(
            "(() => { const field = document.getElementById('name'); field.focus(); field.blur(); return { active: document.activeElement, focused: field.focused }; })()",
        )
        .await
        .unwrap();
    assert_eq!(
        focus,
        serde_json::json!({
            "active": null,
            "focused": false,
        })
    );
    assert_eq!(engine.revision(), initial_revision + 4);
    let effects = engine.effects_since(initial_revision).unwrap();
    assert!(
        effects
            .effects
            .iter()
            .any(|effect| effect.kind == NativeEventKind::Focus)
    );
    assert!(
        effects
            .effects
            .iter()
            .any(|effect| effect.kind == NativeEventKind::Blur)
    );
    assert!(
        effects
            .effects
            .iter()
            .any(|effect| effect.kind == NativeEventKind::Click)
    );
    let before_action = engine.revision();
    engine
        .evaluate_async(
            "(() => { globalThis.onActionClick = (event) => { globalThis.events.push('action:' + event.target.id); document.getElementById('name').value = 'from-action'; }; document.getElementById('toggle').addEventListener('click', globalThis.onActionClick); })()",
        )
        .await
        .unwrap();
    let action = engine
        .action(NativeAction::Click {
            target: "id=toggle".into(),
        })
        .unwrap();
    assert!(action.accepted);
    assert_eq!(action.revision, before_action + 1);
    assert_eq!(engine.revision(), before_action + 1);
    assert_eq!(
        engine
            .evaluate_async(
                "({ checked: document.getElementById('toggle').checked, value: document.getElementById('name').value, action: globalThis.events.includes('action:toggle') })",
            )
            .await
            .unwrap(),
        serde_json::json!({
            "checked": false,
            "value": "from-action",
            "action": true,
        })
    );
    let before_cancel = engine.revision();
    engine
        .evaluate_async(
            "(() => { const toggle = document.getElementById('toggle'); toggle.removeEventListener('click', globalThis.onActionClick); globalThis.onCancelClick = (event) => { globalThis.events.push('cancel:' + event.target.id); event.preventDefault(); }; toggle.addEventListener('click', globalThis.onCancelClick); })()",
        )
        .await
        .unwrap();
    let canceled = engine
        .action(NativeAction::Click {
            target: "id=toggle".into(),
        })
        .unwrap();
    assert!(canceled.accepted);
    assert_eq!(canceled.revision, before_cancel + 1);
    assert_eq!(engine.revision(), before_cancel + 1);
    assert_eq!(
        engine
            .evaluate_async("document.getElementById('toggle').checked")
            .await
            .unwrap(),
        serde_json::json!(false)
    );
    let before_type = engine.revision();
    engine
        .evaluate_async(
            "(() => { const field = document.getElementById('name'); globalThis.typeEvents = []; field.addEventListener('focus', (event) => globalThis.typeEvents.push(event.type)); field.addEventListener('input', (event) => { globalThis.typeEvents.push(event.type); field.setAttribute('data-input', 'seen'); }); field.addEventListener('change', (event) => globalThis.typeEvents.push(event.type)); })()",
        )
        .await
        .unwrap();
    let typed = engine
        .action(NativeAction::Type {
            target: "id=name".into(),
            text: "typed-by-action".into(),
        })
        .unwrap();
    assert!(typed.accepted);
    assert_eq!(typed.revision, before_type + 1);
    assert_eq!(engine.revision(), before_type + 1);
    assert_eq!(
        engine
            .evaluate_async(
                "({ value: document.getElementById('name').value, marker: document.getElementById('name').getAttribute('data-input'), events: globalThis.typeEvents })",
            )
            .await
            .unwrap(),
        serde_json::json!({
            "value": "typed-by-action",
            "marker": "seen",
            "events": ["focus", "input", "change"],
        })
    );
    engine.close_async().await.unwrap();
}

#[tokio::test]
async fn native_local_pointer_actions_dispatch_browser_event_order() {
    let config = NativeEngineConfig::default()
        .with_fixture(
            "fixture://pointer-actions",
            "<button id='button' style='width:100px;height:24px'>Button</button><div id='source' draggable='true' style='width:100px;height:24px'>Source</div><div id='destination' style='width:100px;height:24px'>Destination</div>",
        )
        .unwrap()
        .with_initial_url("fixture://pointer-actions");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();

    engine
        .evaluate_async(
            "(() => { const button = document.getElementById('button'); const source = document.getElementById('source'); const destination = document.getElementById('destination'); globalThis.pointerEvents = []; globalThis.doubleClicks = 0; button.addEventListener('click', () => globalThis.doubleClicks += 1); button.addEventListener('mouseover', event => pointerEvents.push(event.type + ':' + event.target.id + ':' + event.bubbles + ':' + event.cancelable)); button.addEventListener('mouseenter', event => pointerEvents.push(event.type + ':' + event.target.id + ':' + event.bubbles + ':' + event.cancelable)); source.addEventListener('dragstart', event => pointerEvents.push(event.type + ':' + event.target.id + ':' + event.bubbles + ':' + event.cancelable)); destination.addEventListener('dragenter', event => pointerEvents.push(event.type + ':' + event.target.id + ':' + event.bubbles + ':' + event.cancelable)); destination.addEventListener('dragover', event => pointerEvents.push(event.type + ':' + event.target.id + ':' + event.bubbles + ':' + event.cancelable)); destination.addEventListener('drop', event => pointerEvents.push(event.type + ':' + event.target.id + ':' + event.bubbles + ':' + event.cancelable)); source.addEventListener('dragend', event => pointerEvents.push(event.type + ':' + event.target.id + ':' + event.bubbles + ':' + event.cancelable)); })()",
        )
        .await
        .unwrap();

    let double_clicked = engine
        .action(NativeAction::DoubleClick {
            target: "id=button".into(),
        })
        .unwrap();
    assert!(double_clicked.accepted);
    assert_eq!(
        engine
            .evaluate_async("globalThis.doubleClicks")
            .await
            .unwrap(),
        serde_json::json!(2)
    );

    let hovered = engine
        .action(NativeAction::Hover {
            target: "id=button".into(),
        })
        .unwrap();
    assert!(hovered.accepted);

    let dragged = engine
        .action(NativeAction::Drag {
            source: "id=source".into(),
            destination: "id=destination".into(),
        })
        .unwrap();
    assert!(dragged.accepted);
    assert_eq!(
        engine
            .evaluate_async("globalThis.pointerEvents")
            .await
            .unwrap(),
        serde_json::json!([
            "mouseover:button:true:true",
            "mouseenter:button:false:false",
            "dragstart:source:true:true",
            "dragenter:destination:true:true",
            "dragover:destination:true:true",
            "drop:destination:true:true",
            "dragend:source:true:false",
        ])
    );
    let effects = engine.effects_since(0).unwrap();
    assert!(
        effects
            .effects
            .iter()
            .any(|effect| effect.kind == NativeEventKind::MouseOver)
    );
    assert!(
        effects
            .effects
            .iter()
            .any(|effect| effect.kind == NativeEventKind::DragEnd)
    );
    engine.close_async().await.unwrap();
}

