#[tokio::test]
async fn native_runtime_session_loads_bounded_external_http_html_without_cdp() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for _ in 0..3 {
            let (mut stream, _) = listener.accept().await.unwrap();
            let mut request = [0_u8; 4096];
            let read = stream.read(&mut request).await.unwrap();
            let request = String::from_utf8_lossy(&request[..read]);
            let path = request.split_whitespace().nth(1).unwrap_or("/");
            let (status, content_type, location, body) = if path.starts_with("/redirect") {
                ("302 Found", "text/plain", Some("/page"), "")
            } else if path.starts_with("/page") {
                (
                    "200 OK",
                    "text/html; charset=utf-8",
                    None,
                    "<title>Native HTTP</title><p>External native page</p>",
                )
            } else {
                ("200 OK", "application/json", None, "{\"not\":\"html\"}")
            };
            let location_header =
                location.map_or_else(String::new, |value| format!("Location: {value}\r\n"));
            let response = format!(
                "HTTP/1.1 {status}\r\nContent-Type: {content_type}\r\n{location_header}Content-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let initial_url = format!("http://{address}/redirect#section");
    let session = BrowserRuntimeSession::connect_native(
        NativeEngineConfig::default().with_initial_url(initial_url),
    )
    .await
    .unwrap();
    let evidence = session.evidence(EvidenceLevel::Compact).await.unwrap();
    assert_eq!(evidence.url, format!("http://{address}/page#section"));
    assert_eq!(evidence.title, "Native HTTP");
    assert_eq!(evidence.visible_text, "External native page");

    let error = session
        .navigate(format!("http://{address}/not-html"))
        .await
        .unwrap_err()
        .to_string();
    assert!(error.contains("unsupported content type"), "{error}");
    session.close().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_evaluates_persistent_script_realm() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let mut request = [0_u8; 4096];
        let _ = stream.read(&mut request).await.unwrap();
        let body = "<html><head><title>Script</title></head><body><p id='copy'>Native <span id='old-copy'>script</span> page</p></body></html>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine.evaluate_async("6 * 7").await.unwrap(),
        serde_json::json!(42)
    );
    assert_eq!(
        engine.evaluate_async("document.title").await.unwrap(),
        serde_json::json!("Script")
    );
    assert_eq!(
        engine.evaluate_async("document.readyState").await.unwrap(),
        serde_json::json!("complete")
    );
    assert_eq!(
        engine.evaluate_async("location.origin").await.unwrap(),
        serde_json::json!(format!("http://{address}"))
    );
    assert_eq!(
        engine
            .evaluate_async("document.querySelector('p').textContent")
            .await
            .unwrap(),
        serde_json::json!("Native script page")
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const paragraph = document.getElementById('copy'); const first = paragraph.firstChild; const old = document.getElementById('old-copy'); const last = paragraph.lastChild; return [first.nodeType, first.nodeValue, first.parentNode === paragraph, first.nextSibling === old, last.nodeType, last.nodeValue, paragraph.childNodes instanceof NodeList, paragraph.children instanceof HTMLCollection, paragraph.childNodes.length, paragraph.children.length, paragraph.children[0] === old]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([3, "Native ", true, true, 3, " page", true, true, 3, 1, true])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const paragraph = document.querySelector('body > p#copy'); const old = document.querySelector('p#copy > span#old-copy'); const classes = paragraph.classList; classes.add('article', 'featured'); classes.toggle('selected', true); return [paragraph.matches('p#copy.article'), paragraph.closest('body') === document.body, paragraph.querySelector('span#old-copy') === old, paragraph.querySelectorAll('span, #old-copy').length, paragraph.getElementsByClassName('featured').length, classes.length, classes.contains('article'), classes.contains('selected'), paragraph.getAttribute('class')]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([true, true, true, 1, 0, 3, true, true, "article featured selected"])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const paragraph = document.getElementById('copy'); const style = paragraph.style; style.setProperty('color', 'red'); style.width = '120px'; style.setProperty('display', 'block', 'IMPORTANT'); const removed = style.removeProperty('color'); const dataset = paragraph.dataset; dataset.articleId = 42; dataset.enabled = true; const names = Object.keys(dataset).sort(); delete dataset.enabled; const detached = document.createElement('aside'); detached.dataset.kind = 'detached'; detached.style.display = 'block'; return [removed, style.width, style.getPropertyPriority('display'), style.item(0), style.length, style.cssText, dataset.articleId, dataset.enabled, names, paragraph.getAttribute('data-article-id'), paragraph.hasAttribute('data-enabled'), paragraph.style === style, detached.dataset.kind, detached.style.display]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([
            "red",
            "120px",
            "important",
            "width",
            2,
            "width: 120px; display: block !important;",
            "42",
            null,
            ["articleId", "enabled"],
            "42",
            false,
            true,
            "detached",
            "block",
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("(() => { const paragraph = document.getElementById('copy'); paragraph.textContent = 'Updated & literal'; return [paragraph.textContent, paragraph.innerText]; })()")
            .await
            .unwrap(),
        serde_json::json!(["Updated & literal", "Updated & literal"])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "[document.getElementById('copy').textContent, document.getElementById('old-copy')]"
            )
            .await
            .unwrap(),
        serde_json::json!(["Updated & literal", null])
    );
    assert_eq!(
        engine
            .evaluate_async("(() => { const paragraph = document.getElementById('copy'); paragraph.innerHTML = \"<strong id='new-copy'>Updated &amp; literal</strong>\"; return [paragraph.innerHTML, paragraph.textContent]; })()")
            .await
            .unwrap(),
        serde_json::json!(["<strong id=\"new-copy\">Updated &amp; literal</strong>", "Updated & literal"])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const copy = document.getElementById('copy'); const first = copy.firstChild; return [copy.innerHTML, copy.textContent, document.getElementById('old-copy'), document.getElementById('new-copy').textContent, first.nodeType, first.nodeValue, first.parentNode === copy, copy.childNodes.length, copy.children.length]; })()"
            )
            .await
            .unwrap(),
        serde_json::json!(["<strong id=\"new-copy\">Updated &amp; literal</strong>", "Updated & literal", null, "Updated & literal", 1, null, true, 1, 1])
    );
    assert_eq!(
        engine
            .evaluate_async("document.getElementById('new-copy').remove(); true")
            .await
            .unwrap(),
        serde_json::json!(true)
    );
    assert_eq!(
        engine
            .evaluate_async("document.getElementById('new-copy')")
            .await
            .unwrap(),
        serde_json::Value::Null
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const host = document.createElement('article'); host.setAttribute('id', 'created-copy'); const child = document.createElement('b'); const text = document.createTextNode('created'); text.textContent = 'created'; child.appendChild(text); host.appendChild(child); document.body.appendChild(host); const children = host.children; const nodes = host.childNodes; const extra = document.createElement('i'); const extraText = document.createTextNode('!'); extra.appendChild(extraText); host.insertBefore(extra, child); const inserted = [children.length, nodes.length, host.firstChild === extra, host.lastChild === child, extra.firstChild === extraText, extraText.parentNode === extra, host.contains(extraText), document.contains(host)]; host.replaceChild(child, extra); return [host.parentElement === document.body, child.parentElement === host, text.parentNode === child, host.textContent, host.innerHTML, inserted, children.length, nodes.length, host.firstChild === child, host.lastChild === child]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([true, true, true, "created", "<b>created</b>", [2, 2, true, true, true, true, true, true], 1, 1, true, true])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const host = document.getElementById('created-copy'); const first = host.firstChild; return [host.innerHTML, host.textContent, first && first.tagName, first && first.nodeType, first && first.parentNode === host, host.children.length, host.childNodes.length, host.firstElementChild === first, host.lastChild === first]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!(["<b>created</b>", "created", "B", 1, true, 1, 1, true, true])
    );
    assert_eq!(
        engine
            .evaluate_async("await Promise.resolve(42)")
            .await
            .unwrap(),
        serde_json::json!(42)
    );
    let pending_error = engine
        .evaluate_async("await new Promise(() => {})")
        .await
        .unwrap_err();
    assert!(
        pending_error
            .to_string()
            .contains("top-level await remained pending")
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.answer = (globalThis.answer || 0) + 1; answer")
            .await
            .unwrap(),
        serde_json::json!(1)
    );
    assert_eq!(
        engine.evaluate_async("answer").await.unwrap(),
        serde_json::json!(1)
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_document_fragments_cross_the_http_boundary() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/fragment"));
        let body = "<html><body><div id='mount'></div></body></html>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/fragment")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const mount = document.getElementById('mount'); const fragment = document.createDocumentFragment(); const heading = document.createElement('h1'); heading.textContent = 'Native'; fragment.append('before-', heading); const detached = document.createElement('aside'); fragment.prepend(detached); const staged = [fragment instanceof DocumentFragment, fragment.ownerDocument === document, fragment.childNodes.length, detached.parentNode === fragment, detached.parentElement === null]; mount.appendChild(fragment); const text = document.createTextNode('-after'); heading.after(text); return [staged, fragment.childNodes.length, mount.innerHTML, mount.textContent, heading.parentElement === mount, text.parentNode === heading.parentNode, mount.childNodes.length]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([[
            true, true, 3, true, true
        ], 0, "<aside></aside>before-<h1>Native</h1>-after", "before-Native-after", true, true, 4])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const fragment = document.createDocumentFragment(); fragment.innerHTML = '<section data-source=\"http\"><em>Parsed &amp; ready</em> tail</section><hr>'; const section = fragment.firstElementChild; const em = fragment.querySelector('em'); const before = [fragment.innerHTML, fragment.childNodes.length, section.getAttribute('data-source'), em.textContent, section.parentNode === fragment]; const mount = document.getElementById('mount'); mount.appendChild(fragment); return [before, fragment.innerHTML, mount.querySelector('em') === em, mount.innerHTML]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([
            [
                "<section data-source=\"http\"><em>Parsed &amp; ready</em> tail</section><hr>",
                2,
                "http",
                "Parsed & ready",
                true,
            ],
            "",
            true,
            "<aside></aside>before-<h1>Native</h1>-after<section data-source=\"http\"><em>Parsed &amp; ready</em> tail</section><hr>",
        ])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const fragment = document.createDocumentFragment(); fragment.innerHTML = '<!doctype html><!--ignored--><div title=\"a > b\">before<script>if (a < b) x = \"</div>\";</script><textarea>&lt;em&gt;safe&lt;/em&gt;</textarea></div>'; const div = fragment.firstElementChild; const script = div.querySelector('script'); const textarea = div.querySelector('textarea'); return [fragment.childNodes.length, div.getAttribute('title'), script.textContent, textarea.textContent, div.querySelector('em') === null]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([2, "a > b", "if (a < b) x = \"</div>\";", "<em>safe</em>", true])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const source = document.createElement('section'); source.setAttribute('id', 'moving-source'); const moved = document.createElement('b'); source.appendChild(moved); document.body.appendChild(source); const fragment = document.createDocumentFragment(); fragment.appendChild(moved); const stable = document.createElement('i'); fragment.appendChild(stable); const records = []; const observer = new MutationObserver(entries => records.push(entries.map(record => ({ type: record.type, target: record.target === fragment, added: record.addedNodes.map(node => node.localName || node.nodeName), removed: record.removedNodes.map(node => node.localName || node.nodeName), previous: record.previousSibling && (record.previousSibling.localName || record.previousSibling.nodeName), next: record.nextSibling && (record.nextSibling.localName || record.nextSibling.nodeName) })))); observer.observe(fragment, { childList: true, subtree: true }); const inserted = document.createElement('em'); fragment.insertBefore(inserted, stable); stable.remove(); globalThis.fragmentMutationLog = records; return [moved.parentNode === fragment, source.childNodes.length, fragment.childNodes.length]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([true, 0, 2])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.fragmentMutationLog")
            .await
            .unwrap(),
        serde_json::json!([[
            {
                "type": "childList",
                "target": true,
                "added": ["em"],
                "removed": [],
                "previous": "b",
                "next": "i",
            },
            {
                "type": "childList",
                "target": true,
                "added": [],
                "removed": ["i"],
                "previous": "em",
                "next": null,
            },
        ]])
    );
    assert_eq!(
        engine
            .evaluate_async("document.getElementById('moving-source').childNodes.length")
            .await
            .unwrap(),
        serde_json::json!(0)
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const reflected = document.createElement('label'); reflected.id = 'http-property-id'; reflected.className = 'http alpha'; document.body.appendChild(reflected); const assigned = [reflected.id, reflected.className, reflected.getAttribute('id'), reflected.getAttribute('class'), document.getElementById('http-property-id') === reflected, document.querySelector('.alpha') === reflected]; reflected.setAttribute('id', 'http-attribute-id'); reflected.removeAttribute('class'); reflected.title = 'HTTP title'; reflected.name = 'http-field'; reflected.required = true; reflected.readOnly = true; reflected.type = 'BUTTON'; const form = [reflected.title, reflected.name, reflected.required, reflected.readOnly, reflected.type, reflected.getAttribute('title'), reflected.getAttribute('name'), reflected.getAttribute('required'), reflected.getAttribute('readonly'), reflected.getAttribute('type')]; reflected.required = false; reflected.readOnly = false; return { assigned, method: [reflected.id, reflected.className, reflected.getAttribute('id'), reflected.getAttribute('class'), reflected.hasAttribute('class'), document.getElementById('http-attribute-id') === reflected], form, cleared: [reflected.required, reflected.readOnly, reflected.hasAttribute('required'), reflected.hasAttribute('readonly')] }; })()",
            )
            .await
            .unwrap(),
        serde_json::json!({
            "assigned": ["http-property-id", "http alpha", "http-property-id", "http alpha", true, true],
            "method": ["http-attribute-id", "", "http-attribute-id", null, false, true],
            "form": ["HTTP title", "http-field", true, true, "button", "HTTP title", "http-field", "", "", "BUTTON"],
            "cleared": [false, false, false, false],
        })
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const reflected = document.getElementById('http-attribute-id'); return [reflected.id, reflected.className, reflected.getAttribute('id'), reflected.getAttribute('class'), document.querySelector('#http-attribute-id') === reflected, reflected.title, reflected.name, reflected.required, reflected.readOnly, reflected.type]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!(["http-attribute-id", "", "http-attribute-id", null, true, "HTTP title", "http-field", false, false, "button"])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const target = document.createElement('article'); document.body.appendChild(target); const log = []; const observer = new MutationObserver(records => log.push(records.map(record => ({ type: record.type, added: record.addedNodes.map(node => node.localName || node.nodeName), removed: record.removedNodes.map(node => node.localName || node.nodeName) })))); observer.observe(target, { childList: true }); target.innerHTML = '<div id=inner><span>Hi &amp; there</span></div>tail'; globalThis.httpElementInnerHtmlMutationLog = log; return [target.innerHTML, target.textContent, target.querySelector('#inner') !== null, target.querySelector('span').textContent, document.getElementById('inner') !== null, target.childNodes.length]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!(["<div id=\"inner\"><span>Hi &amp; there</span></div>tail", "Hi & theretail", true, "Hi & there", true, 2])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.httpElementInnerHtmlMutationLog")
            .await
            .unwrap(),
        serde_json::json!([[
            {
                "type": "childList",
                "added": ["div", "#text"],
                "removed": [],
            }
        ]])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const target = document.createElement('p'); document.body.appendChild(target); const log = []; const observer = new MutationObserver(records => log.push(records.map(record => ({ type: record.type, added: record.addedNodes.map(node => node.localName || node.nodeName), removed: record.removedNodes.map(node => node.localName || node.nodeName) })))); observer.observe(target, { childList: true }); target.textContent = 'http text'; globalThis.httpElementTextContentMutationLog = log; return [target.textContent, target.firstChild.nodeType, target.firstChild.nodeValue, target.childNodes.length, target.firstChild.parentNode === target]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!(["http text", 3, "http text", 1, true])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.httpElementTextContentMutationLog")
            .await
            .unwrap(),
        serde_json::json!([[
            {
                "type": "childList",
                "added": ["#text"],
                "removed": [],
            }
        ]])
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_location_navigation_crosses_worker_boundary() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for (expected_path, body) in [
            ("/start", "<title>Start</title><p>Initial</p>"),
            ("/destination", "<title>Destination</title><p>Arrived</p>"),
            ("/replaced", "<title>Replaced</title><p>Rewritten</p>"),
        ] {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request = read_http_request(&mut stream).await;
            assert_eq!(request.split_whitespace().nth(1), Some(expected_path));
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/start")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(engine.history().len(), 1);
    assert_eq!(
        engine
            .evaluate_async("[location.href, location.origin, location.pathname]")
            .await
            .unwrap(),
        serde_json::json!([
            format!("http://{address}/start"),
            format!("http://{address}"),
            "/start"
        ])
    );

    engine
        .evaluate_async("location.assign('/destination')")
        .await
        .unwrap();
    assert_eq!(
        engine.snapshot().unwrap().url,
        format!("http://{address}/destination")
    );
    assert_eq!(engine.snapshot().unwrap().title, "Destination");
    assert_eq!(engine.history().len(), 2);

    engine
        .evaluate_async("location.replace('/replaced')")
        .await
        .unwrap();
    assert_eq!(
        engine.snapshot().unwrap().url,
        format!("http://{address}/replaced")
    );
    assert_eq!(engine.snapshot().unwrap().title, "Replaced");
    assert_eq!(engine.history().len(), 2);
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

