#[tokio::test]
async fn native_local_inline_script_failure_dispatches_error_without_aborting_document() {
    let config = NativeEngineConfig::default()
        .with_fixture(
            "fixture://inline-script-error",
            r#"
                <script>
                    globalThis.inlineEvents = [];
                    globalThis.windowEvents = [];
                    globalThis.onerrorEvents = [];
                    window.addEventListener('error', event => windowEvents.push([
                        event.message,
                        event.filename,
                        event.lineno,
                        event.colno,
                        event.error instanceof Error,
                        event.target === window,
                    ]));
                    window.onerror = (message, filename, line, column, error) => onerrorEvents.push([
                        message,
                        filename,
                        line,
                        column,
                        error instanceof Error,
                    ]);
                    const brokenClassic = document.getElementById('broken-classic');
                    brokenClassic.addEventListener('error', event => inlineEvents.push([
                        'classic',
                        event.message,
                        event.filename,
                        event.error instanceof Error,
                    ]));
                    const brokenModule = document.getElementById('broken-module');
                    brokenModule.addEventListener('error', event => inlineEvents.push([
                        'module',
                        event.message,
                        event.filename,
                        event.error instanceof Error,
                    ]));
                </script>
                <script id='broken-classic'>
                    throw new Error('inline classic boom');
                    globalThis.inlineRan = true;
                </script>
                <script id='broken-module' type='module'>
                    throw new Error('inline module boom');
                    globalThis.moduleInlineRan = true;
                </script>
                <title>Inline error is isolated</title>
                <p>Document committed</p>
            "#,
        )
        .unwrap()
        .with_initial_url("fixture://inline-script-error");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();

    let snapshot = engine.snapshot().unwrap();
    assert_eq!(snapshot.url, "fixture://inline-script-error");
    assert_eq!(snapshot.title, "Inline error is isolated");
    assert_eq!(snapshot.visible_text, "Document committed");
    assert_eq!(
        engine
            .evaluate_async(
                "globalThis.inlineEvents.map(event => [event[0], event[1].includes(event[0] === 'classic' ? 'inline classic boom' : 'inline module boom'), event[2], event[3]])",
            )
            .await
            .unwrap(),
        serde_json::json!([
            ["classic", true, "fixture://inline-script-error", true],
            ["module", true, "fixture://inline-script-error", true],
        ])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "globalThis.windowEvents.map(event => [event[0].includes('inline classic boom'), event[1], event[2], event[3], event[4], event[5]])",
            )
            .await
        .unwrap(),
        serde_json::json!([
            [true, "fixture://inline-script-error", 0, 0, true, true],
            [false, "fixture://inline-script-error", 0, 0, true, true],
        ])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "globalThis.onerrorEvents.map(event => [event[0].includes('inline classic boom'), event[1], event[2], event[3], event[4]])",
            )
            .await
        .unwrap(),
        serde_json::json!([
            [true, "fixture://inline-script-error", 0, 0, true],
            [false, "fixture://inline-script-error", 0, 0, true],
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("[Boolean(globalThis.inlineRan), Boolean(globalThis.moduleInlineRan)]")
            .await
            .unwrap(),
        serde_json::json!([false, false])
    );
    assert_eq!(
        engine.evaluate_async("document.readyState").await.unwrap(),
        serde_json::json!("complete")
    );
    engine.close_async().await.unwrap();
}

#[tokio::test]
async fn native_local_unhandled_rejection_dispatches_window_event() {
    let config = NativeEngineConfig::default()
        .with_fixture(
            "fixture://unhandled-rejection",
            r#"
                <script>
                    globalThis.rejectionEvents = [];
                    globalThis.handlerEvents = [];
                    globalThis.handledEvents = [];
                    globalThis.handledHandlerEvents = [];
                    window.addEventListener('unhandledrejection', event => rejectionEvents.push([
                        String(event.reason).includes('first unhandled'),
                        String(event.reason).includes('second unhandled'),
                        String(event.reason).includes('late handled'),
                        event.promise === null,
                        event instanceof PromiseRejectionEvent,
                        event.bubbles,
                        event.cancelable,
                        event.target === window,
                    ]));
                    window.onunhandledrejection = event => handlerEvents.push([
                        String(event.reason).includes('first unhandled'),
                        String(event.reason).includes('second unhandled'),
                    ]);
                    window.addEventListener('rejectionhandled', event => handledEvents.push([
                        String(event.reason).includes('late handled'),
                        event.promise === null,
                        event instanceof PromiseRejectionEvent,
                        event.bubbles,
                        event.cancelable,
                        event.target === window,
                    ]));
                    window.onrejectionhandled = event => handledHandlerEvents.push(
                        String(event.reason).includes('late handled')
                    );
                    Promise.reject('handled boom').catch(() => {});
                    Promise.reject('first unhandled');
                    Promise.reject('second unhandled');
                    globalThis.lateRejection = Promise.reject('late handled');
                    globalThis.afterRejection = true;
                </script>
                <title>Unhandled rejection is observable</title>
                <p>Document committed</p>
            "#,
        )
        .unwrap()
        .with_initial_url("fixture://unhandled-rejection");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();

    let snapshot = engine.snapshot().unwrap();
    assert_eq!(snapshot.url, "fixture://unhandled-rejection");
    assert_eq!(snapshot.title, "Unhandled rejection is observable");
    assert_eq!(snapshot.visible_text, "Document committed");
    assert_eq!(
        engine
            .evaluate_async("globalThis.rejectionEvents")
            .await
            .unwrap(),
        serde_json::json!([
            [true, false, false, true, true, false, true, true],
            [false, true, false, true, true, false, true, true],
            [false, false, true, true, true, false, true, true],
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.handlerEvents")
            .await
            .unwrap(),
        serde_json::json!([[true, false], [false, true], [false, false]])
    );
    assert_eq!(
        engine
            .evaluate_async("lateRejection.catch(() => {}); true")
            .await
            .unwrap(),
        serde_json::json!(true)
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.handledEvents")
            .await
            .unwrap(),
        serde_json::json!([[true, true, true, false, false, true]])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.handledHandlerEvents")
            .await
            .unwrap(),
        serde_json::json!([true])
    );
    assert_eq!(
        engine
            .evaluate_async("Boolean(globalThis.afterRejection)")
            .await
            .unwrap(),
        serde_json::json!(true)
    );
    engine.close_async().await.unwrap();
}

