#[tokio::test]
async fn native_content_process_enforces_child_owned_document_limit() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let mut request = [0_u8; 4096];
        let _ = stream.read(&mut request).await.unwrap();
        let body = "x".repeat(128);
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let limits = NativeEngineLimits {
        max_document_bytes: 32,
        ..NativeEngineLimits::default()
    };
    let error = match BrowserRuntimeSession::connect_native(
        NativeEngineConfig::default()
            .with_limits(limits)
            .with_initial_url(format!("http://{address}/oversized")),
    )
    .await
    {
        Ok(_) => panic!("oversized content unexpectedly initialized"),
        Err(error) => error.to_string(),
    };
    assert!(error.contains("HTTP document exceeds limit 32"), "{error}");
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_commits_recovered_malformed_html() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for _ in 0..2 {
            let (mut stream, _) = listener.accept().await.unwrap();
            let mut request = [0_u8; 4096];
            let read = stream.read(&mut request).await.unwrap();
            let request = String::from_utf8_lossy(&request[..read]);
            let path = request.split_whitespace().nth(1).unwrap_or("/");
            let body = if path.starts_with("/broken") {
                "<p title='unfinished>"
            } else {
                "<title>Stable</title><p>Current document</p>"
            };
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let stable_url = format!("http://{address}/stable");
    let broken_url = format!("http://{address}/broken");
    let session = BrowserRuntimeSession::connect_native(
        NativeEngineConfig::default().with_initial_url(stable_url),
    )
    .await
    .unwrap();
    let before = session.evidence(EvidenceLevel::Compact).await.unwrap();
    let navigation = session.navigate(broken_url.clone()).await.unwrap();
    assert_eq!(navigation.url, broken_url);
    assert_eq!(navigation.revision, before.revision + 1);
    let after = session.evidence(EvidenceLevel::Compact).await.unwrap();
    assert_eq!(after.url, navigation.url);
    assert!(after.title.is_empty());
    assert_eq!(after.visible_text, "<p title='unfinished>");
    assert!(after.complete);
    session.close().await.unwrap();
    server.await.unwrap();
}

