    assert_eq!(one_command.1, NativeTextDecorationStyle::Wavy);
    assert_eq!(one_command.2, 1);
    assert_eq!(one_command.3, 0);
    assert_eq!(two_command.1, NativeTextDecorationStyle::Wavy);
