#[test]
fn native_white_space_revert_layer_preserves_modes_and_flow() {
    let document = NativeDocument::parse(
        "<style>.line { display:block; width:32px; line-height:24px; } @layer base { #wrapped { white-space:pre; } #broken { white-space:pre-line; } #inline { white-space:nowrap; } #parent { white-space:pre; } } @layer theme { #wrapped { white-space:pre-wrap; } #broken { white-space:pre-wrap; } #inline { white-space:pre; } } @layer top { #broken { white-space:revert-layer; } } #wrapped { white-space:revert-layer; } #broken { white-space:revert-layer; }</style><div id='wrapped' class='line'>A  B C D E</div><div id='broken' class='line'>A\nB</div><div id='inline' class='line' style='white-space:REVERT-LAYER'> A  B\n C</div><div id='parent' class='line'><span id='child' style='white-space:revert-layer'> E  F</span></div><div id='fallback' class='line' style='white-space:ReVeRt-LaYeR'>A\nB</div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    assert!(document.diagnostics().iter().all(|diagnostic| {
        !(diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && diagnostic.detail == "white-space")
    }));
    let viewport = Viewport {
        width: 40,
        height: 200,
        device_scale_factor_milli: 1000,
    };
    let layout = document.layout(viewport).unwrap();
    let runs_for = |id: &str| {
        let node = document.resolve_target(&format!("id={id}")).unwrap();
        layout
            .text_runs
            .iter()
            .filter(|run| run.node_id == node)
            .map(|run| (run.origin, run.text.as_str()))
            .collect::<Vec<_>>()
    };

    assert_eq!(
        runs_for("wrapped"),
        vec![
            (NativePoint { x: 0, y: 0 }, "A  B"),
            (NativePoint { x: 0, y: 24 }, " C D"),
            (NativePoint { x: 0, y: 48 }, " E"),
        ]
    );
    assert_eq!(
        runs_for("broken"),
        vec![
            (NativePoint { x: 0, y: 72 }, "A"),
            (NativePoint { x: 0, y: 96 }, "B"),
        ]
    );
    assert_eq!(
        runs_for("inline"),
        vec![
            (NativePoint { x: 0, y: 120 }, " A  B"),
            (NativePoint { x: 0, y: 144 }, " C"),
        ]
    );
    assert_eq!(
        runs_for("child"),
        vec![(NativePoint { x: 0, y: 168 }, " E  F")]
    );
    assert_eq!(
        runs_for("fallback"),
        vec![
            (NativePoint { x: 0, y: 192 }, "A"),
            (NativePoint { x: 8, y: 192 }, " B"),
        ]
    );
}

#[test]
fn native_nowrap_collapses_whitespace_without_soft_wrap_and_reaches_root_scroll() {
    let config = NativeEngineConfig::default()
        .with_viewport(Viewport {
            width: 32,
            height: 24,
            device_scale_factor_milli: 1000,
        })
        .with_fixture(
            "fixture://nowrap",
            "<style>#flow { white-space: nowrap; line-height: 24px; }</style><div id='flow'> A   B\n<span id='inline' style='display:inline; white-space:nowrap'> C   D E</span><span id='hidden' style='display:none;white-space:nowrap'> hidden hidden hidden</span></div>",
        )
        .unwrap()
        .with_initial_url("fixture://nowrap");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    let initial = engine.layout().unwrap();
    assert!(initial.content_width > initial.viewport.width);
    assert!(initial.max_scroll_offset().x > 0);
    assert_eq!(initial.max_scroll_offset().y, 0);
    assert!(initial.text_runs.iter().all(|run| run.origin.y == 0));
    assert!(initial.text_runs.iter().any(|run| run.text == "A B"));
    assert!(initial.text_runs.iter().any(|run| run.text == "C D E"));
    assert!(
        initial
            .text_runs
            .iter()
            .all(|run| !run.text.contains("hidden"))
    );

    let unscrolled = engine.rasterize().unwrap();
    let moved = engine
        .action(NativeAction::Scroll {
            delta_x: i32::MAX,
            delta_y: 0,
        })
        .unwrap();
    assert!(moved.accepted);
    assert_eq!(moved.revision, 2);
    assert_eq!(engine.scroll_offset().x, initial.max_scroll_offset().x);
    assert_eq!(engine.scroll_offset().y, 0);
    assert_eq!(
        engine.display_list().unwrap().scroll_offset.x,
        engine.scroll_offset().x
    );
    let scrolled = engine.rasterize().unwrap();
    assert_ne!(unscrolled.rgba(), scrolled.rgba());

    let no_op = engine
        .action(NativeAction::Scroll {
            delta_x: i32::MAX,
            delta_y: 0,
        })
        .unwrap();
    assert!(!no_op.accepted);
    assert_eq!(no_op.revision, 2);
}

