#[test]
fn native_png_capture_matches_complete_logical_pixel_golden() {
    let config = NativeEngineConfig::default()
        .with_viewport(Viewport {
            width: 8,
            height: 6,
            device_scale_factor_milli: 1000,
        })
        .with_fixture(
            "fixture://pixel-golden",
            "<div style='width:4px;height:3px;background-color:red'></div>",
        )
        .unwrap()
        .with_initial_url("fixture://pixel-golden");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    let white = [255, 255, 255, 255];
    let red = [255, 0, 0, 255];
    let expected = [
        [red, red, red, red, white, white, white, white],
        [red, red, red, red, white, white, white, white],
        [red, red, red, red, white, white, white, white],
        [white, white, white, white, white, white, white, white],
        [white, white, white, white, white, white, white, white],
        [white, white, white, white, white, white, white, white],
    ];
    let expected_rgba: Vec<u8> = expected.into_iter().flatten().flatten().collect();

    let before = engine.revision();
    let surface = engine.rasterize().unwrap();
    assert_eq!(surface.rgba(), expected_rgba.as_slice());

    let capture = engine.capture_png().unwrap();
    let decoder = png::Decoder::new(Cursor::new(capture));
    let mut reader = decoder.read_info().unwrap();
    let mut decoded = vec![0; reader.output_buffer_size()];
    let output = reader.next_frame(&mut decoded).unwrap();
    assert_eq!((output.width, output.height), (8, 6));
    assert_eq!(&decoded[..expected_rgba.len()], expected_rgba.as_slice());
    assert_eq!(engine.revision(), before);
}

#[tokio::test]
async fn native_backend_captures_png_without_mutating_revision_and_denies_other_formats() {
    let config = NativeEngineConfig::default()
        .with_viewport(Viewport {
            width: 8,
            height: 8,
            device_scale_factor_milli: 1000,
        })
        .with_fixture(
            "fixture://capture",
            "<style>#card { width: 8px; height: 8px; background-color: red; }</style><div id='card'>A</div>",
        )
        .unwrap()
        .with_initial_url("fixture://capture");
    let backend = NativeEngineBackend::new(config).unwrap();
    let dispatcher = BrowserBackendDispatcher::new(&backend);
    dispatcher.initialize().await.unwrap();
    let before = dispatcher
        .evidence(EvidenceRequest {
            context_id: "native-context".into(),
            level: EvidenceLevel::Compact,
        })
        .await
        .unwrap();

    let capture = dispatcher
        .capture(CaptureRequest {
            context_id: "native-context".into(),
            format: CaptureFormat::Png,
        })
        .await
        .unwrap();
    assert_eq!(capture.format, CaptureFormat::Png);
    assert_eq!(&capture.bytes[..8], b"\x89PNG\r\n\x1a\n");
    let decoder = png::Decoder::new(Cursor::new(capture.bytes));
    let mut reader = decoder.read_info().unwrap();
    let mut decoded = vec![0; reader.output_buffer_size()];
    let output = reader.next_frame(&mut decoded).unwrap();
    assert_eq!((output.width, output.height), (8, 8));
    assert_eq!(&decoded[..4], &[255, 0, 0, 255]);

    let after = dispatcher
        .evidence(EvidenceRequest {
            context_id: "native-context".into(),
            level: EvidenceLevel::Compact,
        })
        .await
        .unwrap();
    assert_eq!(after.revision, before.revision);

    let jpeg = dispatcher
        .capture(CaptureRequest {
            context_id: "native-context".into(),
            format: CaptureFormat::Jpeg,
        })
        .await
        .unwrap_err();
    assert!(matches!(
        jpeg,
        glass_browser::browser_backend::BrowserBackendError::UnsupportedOperation {
            operation, ..
        } if operation == "capture"
    ));
    dispatcher.close().await.unwrap();
}

#[tokio::test]
async fn native_backend_composes_nested_frame_surfaces_into_capture() {
    let config = NativeEngineConfig::default()
        .with_viewport(Viewport {
            width: 24,
            height: 12,
            device_scale_factor_milli: 1000,
        })
        .with_fixture(
            "fixture://frame-composite-parent",
            "<iframe id='child' style='display:block;width:8px;height:6px' src='fixture://frame-composite-child'></iframe>",
        )
        .unwrap()
        .with_fixture(
            "fixture://frame-composite-child",
            "<iframe id='grand' style='display:block;width:4px;height:3px' src='fixture://frame-composite-grand'></iframe><div style='display:block;width:8px;height:6px;background-color:blue'></div>",
        )
        .unwrap()
        .with_fixture(
            "fixture://frame-composite-grand",
            "<div style='display:block;width:4px;height:3px;background-color:red'></div>",
        )
        .unwrap()
        .with_initial_url("fixture://frame-composite-parent");
    let backend = NativeEngineBackend::new(config).unwrap();
    let dispatcher = BrowserBackendDispatcher::new(&backend);
    dispatcher.initialize().await.unwrap();

    let capture = dispatcher
        .capture(CaptureRequest {
            context_id: "native-context".into(),
            format: CaptureFormat::Png,
        })
        .await
        .unwrap();
    let decoder = png::Decoder::new(Cursor::new(capture.bytes));
    let mut reader = decoder.read_info().unwrap();
    let mut decoded = vec![0; reader.output_buffer_size()];
    let output = reader.next_frame(&mut decoded).unwrap();
    assert_eq!((output.width, output.height), (24, 12));
    let pixel = |x: usize, y: usize| {
        let index = y
            .saturating_mul(output.line_size)
            .saturating_add(x.saturating_mul(4));
        &decoded[index..index + 4]
    };
    assert_eq!(pixel(1, 1), &[255, 0, 0, 255]);
    assert_eq!(pixel(1, 4), &[0, 0, 255, 255]);
    assert_eq!(pixel(12, 1), &[255, 255, 255, 255]);

    let child = backend
        .list_frames()
        .await
        .unwrap()
        .into_iter()
        .find(|frame| frame.parent_id.is_some())
        .unwrap();
    backend.select_frame(&child.id).await.unwrap();
    assert_eq!(
        backend.inspection_snapshot().unwrap().layout.viewport,
        Viewport {
            width: 8,
            height: 6,
            device_scale_factor_milli: 1000,
        }
    );
    dispatcher.close().await.unwrap();
}

#[tokio::test]
async fn native_backend_routes_point_clicks_into_nested_frame_content() {
    let config = NativeEngineConfig::default()
        .with_viewport(Viewport {
            width: 24,
            height: 12,
            device_scale_factor_milli: 1000,
        })
        .with_fixture(
            "fixture://frame-click-parent",
            "<iframe id='child' style='display:block;width:8px;height:6px' src='fixture://frame-click-child'></iframe>",
        )
        .unwrap()
        .with_fixture(
            "fixture://frame-click-child",
            "<iframe id='grand' style='display:block;width:8px;height:6px' src='fixture://frame-click-grand'></iframe>",
        )
        .unwrap()
        .with_fixture(
            "fixture://frame-click-grand",
            "<input id='inside' style='display:block;width:8px;height:2px' value='before'><input id='next' style='display:block;width:8px;height:2px' value='after'>",
        )
        .unwrap()
        .with_initial_url("fixture://frame-click-parent");
    let backend = NativeEngineBackend::new(config).unwrap();
    let dispatcher = BrowserBackendDispatcher::new(&backend);
    dispatcher.initialize().await.unwrap();

    let clicked = dispatcher
        .action(ActionRequest {
            context_id: "native-context".into(),
            action: SemanticAction::Click {
                target: "point=1,1".into(),
            },
        })
        .await
        .unwrap();
    assert!(clicked.accepted);
    assert_eq!(clicked.revision, 2);

    let typed = dispatcher
        .action(ActionRequest {
            context_id: "native-context".into(),
            action: SemanticAction::KeyPress { key: "a".into() },
        })
        .await
        .unwrap();
    assert!(typed.accepted);
    assert_eq!(typed.revision, 3);

    let tabbed = dispatcher
        .action(ActionRequest {
            context_id: "native-context".into(),
            action: SemanticAction::Shortcut {
                shortcut: "Tab".into(),
            },
        })
        .await
        .unwrap();
    assert!(tabbed.accepted);
    assert_eq!(tabbed.revision, 4);

    let reverse_tabbed = dispatcher
        .action(ActionRequest {
            context_id: "native-context".into(),
            action: SemanticAction::Shortcut {
                shortcut: "Shift+Tab".into(),
            },
        })
        .await
        .unwrap();
    assert!(reverse_tabbed.accepted);
    assert_eq!(reverse_tabbed.revision, 5);

    let located = dispatcher
        .action(ActionRequest {
            context_id: "native-context".into(),
            action: SemanticAction::Click {
                target: "id=next".into(),
            },
        })
        .await
        .unwrap();
    assert!(located.accepted);
    assert_eq!(located.revision, 6);

    let frames = backend.list_frames().await.unwrap();
    let child = frames
        .iter()
        .find(|frame| frame.url == "fixture://frame-click-grand")
        .unwrap();
    backend.select_frame(&child.id).await.unwrap();
    let value = dispatcher
        .script(ScriptRequest {
            context_id: "native-context".into(),
            source: "({ active: document.activeElement.id, value: document.getElementById('inside').value })".into(),
        })
        .await
        .unwrap();
    assert_eq!(
        value.value,
        serde_json::json!({"active": "next", "value": "beforea"})
    );
    dispatcher.close().await.unwrap();
}

#[tokio::test]
async fn native_backend_dispatches_vertical_scroll_into_capture() {
    let config = NativeEngineConfig::default()
        .with_viewport(Viewport {
            width: 80,
            height: 24,
            device_scale_factor_milli: 1000,
        })
        .with_fixture(
            "fixture://scroll-dispatch",
            "<div style='display:block;height:24px;background-color:red'>Top</div><button id='bottom' style='display:block;height:24px;background-color:blue'>Bottom</button>",
        )
        .unwrap()
        .with_initial_url("fixture://scroll-dispatch");
    let backend = NativeEngineBackend::new(config).unwrap();
    let dispatcher = BrowserBackendDispatcher::new(&backend);
    dispatcher.initialize().await.unwrap();

    let action = dispatcher
        .action(ActionRequest {
            context_id: "native-context".into(),
            action: SemanticAction::Scroll {
                delta_x: 0,
                delta_y: i32::MAX,
            },
        })
        .await
        .unwrap();
    assert_eq!(action.revision, 2);
    assert!(action.accepted);

    let capture = dispatcher
        .capture(CaptureRequest {
            context_id: "native-context".into(),
            format: CaptureFormat::Png,
        })
        .await
        .unwrap();
    let decoder = png::Decoder::new(Cursor::new(capture.bytes));
    let mut reader = decoder.read_info().unwrap();
    let mut decoded = vec![0; reader.output_buffer_size()];
    let output = reader.next_frame(&mut decoded).unwrap();
    assert_eq!((output.width, output.height), (80, 24));
    let pixel_index = output.line_size + 4;
    assert_eq!(&decoded[pixel_index..pixel_index + 4], &[0, 0, 255, 255]);

    let horizontal_edge = dispatcher
        .action(ActionRequest {
            context_id: "native-context".into(),
            action: SemanticAction::Scroll {
                delta_x: 1,
                delta_y: 0,
            },
        })
        .await
        .unwrap();
    assert!(!horizontal_edge.accepted);
    dispatcher.close().await.unwrap();
}

