#[test]
fn native_css_absolute_position_is_filtered_from_flex_and_grid_items() {
    let document = NativeDocument::parse(
        "<div id='flex' style='display:flex;width:30px;height:10px'><div id='flex-overlay' style='position:absolute;left:2px;top:1px;width:4px;height:4px'></div><div id='flex-flow' style='width:6px;height:4px'></div></div><div id='grid' style='display:grid;width:30px;grid-template-columns:10px 10px'><div id='grid-overlay' style='position:absolute;left:12px;top:1px;width:4px;height:4px'></div><div id='grid-flow' style='height:4px'></div></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let flex_overlay = document.resolve_target("id=flex-overlay").unwrap();
    let flex_flow = document.resolve_target("id=flex-flow").unwrap();
    let grid_overlay = document.resolve_target("id=grid-overlay").unwrap();
    let grid_flow = document.resolve_target("id=grid-flow").unwrap();
    let layout = document
        .layout(Viewport {
            width: 40,
            height: 40,
            device_scale_factor_milli: 1000,
        })
        .unwrap();

    assert_eq!(layout.box_for(flex_overlay).unwrap().x, 2);
    assert_eq!(layout.box_for(flex_overlay).unwrap().y, 1);
    assert_eq!(layout.box_for(flex_flow).unwrap().x, 0);
    assert_eq!(layout.box_for(flex_flow).unwrap().y, 0);
    assert_eq!(layout.box_for(grid_overlay).unwrap().x, 12);
    assert_eq!(layout.box_for(grid_overlay).unwrap().y, 11);
    assert_eq!(layout.box_for(grid_flow).unwrap().x, 0);
    assert_eq!(layout.box_for(grid_flow).unwrap().y, 10);
}

#[test]
fn native_css_fixed_position_stays_viewport_anchored_when_root_scrolls() {
    let config = NativeEngineConfig::default()
        .with_viewport(Viewport {
            width: 32,
            height: 20,
            device_scale_factor_milli: 1000,
        })
        .with_fixture(
            "fixture://fixed",
            "<div style='width:10px;height:5px;overflow:hidden'><button id='fixed' style='display:block;position:fixed;left:20px;top:3px;width:8px;height:4px;background:red'></button></div><div style='height:120px'></div>",
        )
        .unwrap()
        .with_initial_url("fixture://fixed");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();
    let fixed = engine
        .preflight_target("id=fixed", NativePreflightAction::Click)
        .unwrap()
        .node
        .unwrap()
        .node_id;
    let initial = engine.layout().unwrap();
    assert_eq!(
        initial.box_for(fixed),
        Some(NativeRect {
            x: 20,
            y: 3,
            width: 8,
            height: 4,
        })
    );
    assert!(
        initial
            .boxes
            .iter()
            .find(|layout_box| layout_box.node_id == fixed)
            .is_some_and(|layout_box| layout_box.fixed)
    );

    let scrolled = engine
        .action(NativeAction::Scroll {
            delta_x: 0,
            delta_y: 10,
        })
        .unwrap();
    assert!(scrolled.accepted);
    let layout = engine.layout().unwrap();
    assert_eq!(
        layout.box_for(fixed),
        Some(NativeRect {
            x: 20,
            y: 13,
            width: 8,
            height: 4,
        })
    );
    assert_eq!(
        layout.viewport_rect_for(fixed),
        Some(NativeRect {
            x: 20,
            y: 3,
            width: 8,
            height: 4,
        })
    );
    assert_eq!(engine.hit_test(21, 4).unwrap(), Some(fixed));

    let list = engine.display_list().unwrap();
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, rect, color, .. }
                if *node_id == fixed
                    && *rect == NativeRect { x: 20, y: 13, width: 8, height: 4 }
                    && *color == NativeColor::RED
        )
    }));
    assert_eq!(
        engine.rasterize().unwrap().pixel(20, 3),
        Some([255, 0, 0, 255])
    );
}

#[test]
fn native_css_sticky_position_preserves_flow_and_sticks_to_viewport() {
    let config = NativeEngineConfig::default()
        .with_viewport(Viewport {
            width: 32,
            height: 20,
            device_scale_factor_milli: 1000,
        })
        .with_fixture(
            "fixture://sticky",
            "<div id='container' style='width:24px;height:100px'><div style='height:30px'></div><button id='sticky' style='display:block;position:sticky;top:2px;width:8px;height:4px;background:red'>S</button><button id='tail' style='display:block;width:0px;height:100px'></button></div>",
        )
        .unwrap()
        .with_initial_url("fixture://sticky");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();
    let sticky = engine
        .preflight_target("id=sticky", NativePreflightAction::Click)
        .unwrap()
        .node
        .unwrap()
        .node_id;
    let tail = engine
        .preflight_target("id=tail", NativePreflightAction::Click)
        .unwrap()
        .node
        .unwrap()
        .node_id;

    let initial = engine.layout().unwrap();
    assert_eq!(
        initial.box_for(sticky),
        Some(NativeRect {
            x: 0,
            y: 30,
            width: 8,
            height: 4,
        })
    );
    assert_eq!(initial.box_for(tail).unwrap().y, 34);
    assert!(
        initial
            .boxes
            .iter()
            .find(|layout_box| layout_box.node_id == sticky)
            .is_some_and(|layout_box| layout_box.sticky)
    );
    assert!(
        initial
            .text_runs
            .iter()
            .find(|text_run| text_run.node_id == sticky)
            .is_some_and(|text_run| text_run.sticky)
    );

    let scrolled = engine
        .action(NativeAction::Scroll {
            delta_x: 0,
            delta_y: 40,
        })
        .unwrap();
    assert!(scrolled.accepted);
    let layout = engine.layout().unwrap();
    assert_eq!(
        layout.box_for(sticky),
        Some(NativeRect {
            x: 0,
            y: 42,
            width: 8,
            height: 4,
        })
    );
    assert_eq!(layout.viewport_rect_for(sticky).unwrap().y, 2);
    assert_eq!(layout.box_for(tail).unwrap().y, 34);
    assert_eq!(engine.hit_test(1, 3).unwrap(), Some(sticky));

    let list = engine.display_list().unwrap();
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, rect, color, .. }
                if *node_id == sticky
                    && *rect == NativeRect { x: 0, y: 42, width: 8, height: 4 }
                    && *color == NativeColor::RED
        )
    }));
    assert_eq!(
        engine.rasterize().unwrap().pixel(0, 2),
        Some([255, 0, 0, 255])
    );
}

#[test]
fn native_css_sticky_position_releases_at_containing_block_end() {
    let config = NativeEngineConfig::default()
        .with_viewport(Viewport {
            width: 32,
            height: 20,
            device_scale_factor_milli: 1000,
        })
        .with_fixture(
            "fixture://sticky-boundary",
            "<div id='container' style='width:24px;height:60px'><div style='height:20px'></div><button id='sticky' style='display:block;position:sticky;top:0;width:8px;height:10px;background:blue'></button><button style='display:block;height:100px'></button></div>",
        )
        .unwrap()
        .with_initial_url("fixture://sticky-boundary");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();
    let sticky = engine
        .preflight_target("id=sticky", NativePreflightAction::Click)
        .unwrap()
        .node
        .unwrap()
        .node_id;

    engine
        .action(NativeAction::Scroll {
            delta_x: 0,
            delta_y: 45,
        })
        .unwrap();
    let near_end = engine.layout().unwrap();
    assert_eq!(near_end.box_for(sticky).unwrap().y, 45);
    assert_eq!(near_end.viewport_rect_for(sticky).unwrap().y, 0);

    engine
        .action(NativeAction::Scroll {
            delta_x: 0,
            delta_y: 15,
        })
        .unwrap();
    let after_end = engine.layout().unwrap();
    assert_eq!(after_end.box_for(sticky).unwrap().y, 50);
    assert_eq!(after_end.viewport_rect_for(sticky), None);
}

#[test]
fn native_css_z_index_orders_positioned_overlays_for_paint_and_hit_testing() {
    let document = NativeDocument::parse(
        "<button id='high' style='display:block;position:absolute;left:2px;top:2px;width:12px;height:8px;background:blue;z-index:2'>high</button><button id='low' style='display:block;position:absolute;left:2px;top:2px;width:12px;height:8px;background:red;z-index:1'>low</button>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let high = document.resolve_target("id=high").unwrap();
    let low = document.resolve_target("id=low").unwrap();
    let viewport = Viewport {
        width: 24,
        height: 16,
        device_scale_factor_milli: 1000,
    };
    let layout = document.layout(viewport).unwrap();

    assert_eq!(layout.hit_test(3, 3).unwrap(), Some(high));
    assert_eq!(
        layout
            .boxes
            .iter()
            .find(|layout_box| layout_box.node_id == high)
            .map(|layout_box| layout_box.z_index),
        Some(2)
    );
    assert_eq!(
        layout
            .boxes
            .iter()
            .find(|layout_box| layout_box.node_id == low)
            .map(|layout_box| layout_box.z_index),
        Some(1)
    );

    let list = document.display_list(viewport).unwrap();
    let fills = list
        .commands
        .iter()
        .filter_map(|command| match command {
            NativeDisplayCommand::FillRect { node_id, .. } => Some(*node_id),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(fills, vec![low, high]);
    assert_eq!(
        list.rasterize().unwrap().pixel(3, 3),
        Some([0, 0, 255, 255])
    );
}

