#[tokio::test]
async fn native_content_process_reuses_cacheable_external_png_for_duplicate_images() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let png = native_test_png_bytes();
    let server = tokio::spawn(async move {
        for expected_path in ["/page", "/image.png"] {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request = read_http_request(&mut stream).await;
            assert_eq!(request.split_whitespace().nth(1), Some(expected_path));
            if expected_path == "/image.png" {
                let headers = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: image/png\r\nCache-Control: max-age=60\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                    png.len()
                );
                stream.write_all(headers.as_bytes()).await.unwrap();
                stream.write_all(&png).await.unwrap();
            } else {
                let body = "<div style='width:16px'><img id='first' src='/image.png' width='8'><img id='second' src='/image.png' width='8'></div>";
                let response = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
                stream.write_all(response.as_bytes()).await.unwrap();
            }
        }
        match tokio::time::timeout(Duration::from_millis(250), listener.accept()).await {
            Ok(Ok((mut stream, _))) => {
                let _ = read_http_request(&mut stream).await;
                let response =
                    b"HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
                stream.write_all(response).await.unwrap();
                true
            }
            _ => false,
        }
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default()
            .with_viewport(Viewport {
                width: 16,
                height: 8,
                device_scale_factor_milli: 1000,
            })
            .with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    let image_count = engine
        .display_list()
        .unwrap()
        .commands
        .iter()
        .filter(|command| matches!(command, NativeDisplayCommand::Image { .. }))
        .count();
    assert_eq!(image_count, 2);

    engine.close_async().await.unwrap();
    assert!(!server.await.unwrap(), "duplicate image was requested");
}

#[tokio::test]
async fn native_content_process_blocks_csp_disallowed_image_before_request() {
    let _guard = native_content_process_test_lock().lock().await;
    let target_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let target_address = target_listener.local_addr().unwrap();
    let (target_request, target_request_rx) = tokio::sync::oneshot::channel();
    let target_server = tokio::spawn(async move {
        if tokio::time::timeout(Duration::from_secs(1), target_listener.accept())
            .await
            .is_ok()
        {
            let _ = target_request.send(());
        }
    });

    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let _ = read_http_request(&mut stream).await;
        let body = format!("<img id='blocked' src='http://{target_address}/image.png' width='8'>");
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Security-Policy: default-src 'none'; img-src 'none'\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert!(
        tokio::time::timeout(Duration::from_millis(250), target_request_rx)
            .await
            .is_err(),
        "CSP-disallowed image was requested"
    );
    assert!(
        !engine
            .display_list()
            .unwrap()
            .commands
            .iter()
            .any(|command| matches!(command, NativeDisplayCommand::Image { .. }))
    );

    engine.close_async().await.unwrap();
    server.await.unwrap();
    target_server.abort();
    let _ = target_server.await;
}

#[tokio::test]
async fn native_local_url_attributes_resolve_and_persist_through_dom_commands() {
    let config = NativeEngineConfig::default()
        .with_initial_url("fixture://url-properties/path/page")
        .with_fixture(
            "fixture://url-properties/path/page",
            "<a id='link' href='../next?tab=one#part'>next</a><img id='image' src='assets/pixel.png'><form id='form' action='/submit'><input></form><script id='script' src='../scripts/app.js'></script><link id='stylesheet' rel='stylesheet' href='../styles/main.css'>",
        )
        .unwrap();
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();

    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const link = document.getElementById('link'); const image = document.getElementById('image'); const form = document.getElementById('form'); const script = document.getElementById('script'); const stylesheet = document.getElementById('stylesheet'); return [link.href, image.src, form.action, script.src, stylesheet.href, link.getAttribute('href'), image.getAttribute('src')]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([
            "fixture://url-properties/next?tab=one#part",
            "fixture://url-properties/path/assets/pixel.png",
            "fixture://url-properties/submit",
            "fixture://url-properties/scripts/app.js",
            "fixture://url-properties/styles/main.css",
            "../next?tab=one#part",
            "assets/pixel.png",
        ])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { const image = document.getElementById('image'); image.src = '../images/next.png'; return [image.src, image.getAttribute('src')]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([
            "fixture://url-properties/images/next.png",
            "../images/next.png",
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("[document.getElementById('image').src, document.getElementById('image').getAttribute('src')]")
            .await
            .unwrap(),
        serde_json::json!([
            "fixture://url-properties/images/next.png",
            "../images/next.png",
        ])
    );
    engine.close_async().await.unwrap();
}

#[tokio::test]
async fn native_local_namespace_dom_preserves_svg_mathml_and_foreign_content() {
    let mut engine = NativeEngine::new(NativeEngineConfig::default().with_initial_url(
        "data:text/html,%3Cbody%3E%3Csvg%20id%3D%27parsed-svg%27%3E%3Crect%20id%3D%27parsed-rect%27%3E%3C%2Frect%3E%3CforeignObject%20id%3D%27foreign%27%3E%3Cdiv%20id%3D%27foreign-html%27%3Econtent%3C%2Fdiv%3E%3C%2FforeignObject%3E%3C%2Fsvg%3E%3C%2Fbody%3E",
    ))
    .unwrap();
    engine.initialize_async().await.unwrap();

    let result = engine
        .evaluate_async(
            "(() => { const svg = document.getElementById('parsed-svg'); const rect = document.getElementById('parsed-rect'); const foreign = document.getElementById('foreign'); const foreignHtml = document.getElementById('foreign-html'); const created = document.createElementNS('http://www.w3.org/2000/svg', 'circle'); created.id = 'created-circle'; created.setAttribute('cx', '4'); svg.appendChild(created); const math = document.createElementNS('http://www.w3.org/1998/Math/MathML', 'mi'); math.textContent = 'x'; math.id = 'created-math'; document.body.appendChild(math); const nullNamespace = document.createElementNS(null, 'custom-node'); const html = document.createElement('div'); html.innerHTML = '<svg><circle id=inner-circle></circle></svg>'; document.body.appendChild(html); let invalidName = ''; try { document.createElementNS('https://example.com/not-supported', 'x'); } catch (error) { invalidName = error.name; } return { parsed: [svg.namespaceURI, rect.namespaceURI, foreign.namespaceURI, foreignHtml.namespaceURI], created: [created.namespaceURI, created.localName, created.tagName, document.getElementById('created-circle') === created], math: [math.namespaceURI, math.localName, math.tagName], nullNamespace: nullNamespace.namespaceURI, parser: [html.firstElementChild.namespaceURI, html.firstElementChild.firstElementChild.namespaceURI], invalidName }; })()",
        )
        .await
        .unwrap();
    assert_eq!(
        result,
        serde_json::json!({
            "parsed": [
                "http://www.w3.org/2000/svg",
                "http://www.w3.org/2000/svg",
                "http://www.w3.org/2000/svg",
                "http://www.w3.org/1999/xhtml",
            ],
            "created": ["http://www.w3.org/2000/svg", "circle", "circle", true],
            "math": ["http://www.w3.org/1998/Math/MathML", "mi", "mi"],
            "nullNamespace": null,
            "parser": [
                "http://www.w3.org/2000/svg",
                "http://www.w3.org/2000/svg",
            ],
            "invalidName": "NamespaceError",
        })
    );
    engine.close_async().await.unwrap();
}

#[tokio::test]
async fn native_namespaced_attributes_preserve_attr_identity_and_commands() {
    let mut engine = NativeEngine::new(NativeEngineConfig::default().with_initial_url(
        "data:text/html,%3Cbody%3E%3Csvg%20id%3D%27icon%27%20xmlns%3Axlink%3D%27http%3A%2F%2Fwww.w3.org%2F1999%2Fxlink%27%20xlink%3Ahref%3D%27%23old%27%20xml%3Alang%3D%27en%27%3E%3C%2Fsvg%3E%3C%2Fbody%3E",
    ))
    .unwrap();
    engine.initialize_async().await.unwrap();

    let result = engine
        .evaluate_async(
            r#"(() => {
                const xlink = 'http://www.w3.org/1999/xlink';
                const xml = 'http://www.w3.org/XML/1998/namespace';
                const icon = document.getElementById('icon');
                const initial = icon.getAttributeNodeNS(xlink, 'href');
                const ordinaryLookup = icon.getAttributeNode('xlink:href');
                const xmlAttribute = icon.attributes.getNamedItemNS(xml, 'lang');
                const parsed = [
                    icon.getAttributeNS(xlink, 'href'),
                    initial && [initial.name, initial.localName, initial.prefix, initial.namespaceURI, initial.value],
                    ordinaryLookup && ordinaryLookup.namespaceURI,
                    xmlAttribute && [xmlAttribute.name, xmlAttribute.namespaceURI, xmlAttribute.value],
                ];
                icon.setAttributeNS(xlink, 'xlink:href', '#new');
                const updated = icon.getAttributeNodeNS(xlink, 'href');
                updated.value = '#setter';
                const afterSetter = icon.getAttributeNS(xlink, 'href');
                const created = document.createAttributeNS(xlink, 'xlink:title');
                created.value = 'title';
                const replaced = icon.setAttributeNodeNS(xlink, created);
                const createdOwner = created.ownerElement === icon;
                const clone = icon.cloneNode(false);
                const clonedHref = clone.getAttributeNodeNS(xlink, 'href');
                const clonedTitle = clone.attributes.getNamedItemNS(xlink, 'title');
                const parsedContainer = document.createElement('div');
                parsedContainer.innerHTML = "<svg xmlns:xlink='http://www.w3.org/1999/xlink' xlink:href='#inner'></svg>";
                const parsedDetached = parsedContainer.firstElementChild;
                let invalid = '';
                try { icon.setAttributeNS(xlink, 'href', 'wrong namespace prefix'); } catch (error) { invalid = error.name; }
                const map = icon.attributes;
                const mapState = [
                    map.getNamedItemNS(xlink, 'href') === updated,
                    map.getNamedItemNS(xlink, 'title') === created,
                    map.getNamedItemNS(xml, 'lang') === xmlAttribute,
                    map.length,
                ];
                const removed = map.removeNamedItemNS(xlink, 'title');
                icon.removeAttributeNS(xlink, 'href');
                return {
                    parsed,
                    afterSetter,
                    updated: [updated.namespaceURI, updated.localName, updated.prefix, updated.value],
                    created: [created.namespaceURI, created.localName, created.prefix, createdOwner],
                    replaced: replaced === null,
                    clone: [clone.namespaceURI, clonedHref && clonedHref.namespaceURI, clonedHref && clonedHref.value, clonedTitle && clonedTitle.value],
                    detached: [parsedDetached.namespaceURI, parsedDetached.getAttributeNS(xlink, 'href'), parsedDetached.getAttributeNode('xlink:href').namespaceURI],
                    mapState,
                    removed: [removed === created, created.ownerElement === null],
                    final: [icon.getAttributeNS(xlink, 'href'), icon.getAttributeNS(xlink, 'title'), icon.attributes.length],
                    invalid,
                };
            })()"#,
        )
        .await
        .unwrap();
    assert_eq!(
        result,
        serde_json::json!({
            "parsed": [
                "#old",
                [
                    "xlink:href",
                    "href",
                    "xlink",
                    "http://www.w3.org/1999/xlink",
                    "#old",
                ],
                "http://www.w3.org/1999/xlink",
                ["xml:lang", "http://www.w3.org/XML/1998/namespace", "en"],
            ],
            "afterSetter": "#setter",
            "updated": [
                "http://www.w3.org/1999/xlink",
                "href",
                "xlink",
                "#setter",
            ],
            "created": [
                "http://www.w3.org/1999/xlink",
                "title",
                "xlink",
                true,
            ],
            "replaced": true,
            "clone": [
                "http://www.w3.org/2000/svg",
                "http://www.w3.org/1999/xlink",
                "#setter",
                "title",
            ],
            "detached": [
                "http://www.w3.org/2000/svg",
                "#inner",
                "http://www.w3.org/1999/xlink",
            ],
            "mapState": [true, true, true, 5],
            "removed": [true, true],
            "final": [null, null, 3],
            "invalid": "NamespaceError",
        })
    );
    engine.close_async().await.unwrap();
}

#[test]
fn native_flex_sizing_css_wide_resets_reach_layout_and_raster() {
    let document = NativeDocument::parse(
        "<style>.row { display:flex; width:32px; height:8px; gap:2px; align-items:flex-start; } .item { width:4px; height:4px; flex-shrink:0; } #reset { flex:4 5 12px; background-color:red; } #reset { flex:InItIaL; } #longhands { flex-grow:4; flex-shrink:5; flex-basis:12px; background-color:green; } #longhands { flex-grow:UnSeT; } #longhands { flex-shrink:ReVeRt; flex-basis:INITIAL; } #invalid { flex:2 3 8px; background-color:blue; } #invalid { flex:inherit 1 auto; } #important { flex:5 6 10px !important; background-color:black; } #important { flex:initial; }</style><div id='row' class='row'><div id='reset' class='item'>A</div><div id='longhands' class='item'>B</div><div id='invalid' class='item'>C</div><div id='important' class='item'>D</div></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 40,
        height: 16,
        device_scale_factor_milli: 1000,
    };
    let row = document.resolve_target("id=row").unwrap();
    let reset = document.resolve_target("id=reset").unwrap();
    let longhands = document.resolve_target("id=longhands").unwrap();
    let invalid = document.resolve_target("id=invalid").unwrap();
    let important = document.resolve_target("id=important").unwrap();

    let layout = document.layout(viewport).unwrap();
    assert_eq!(layout.box_for(row).unwrap().width, 32);
    let rect = |node_id| layout.box_for(node_id).expect("layout rectangle");
    let reset_rect = rect(reset);
    let longhands_rect = rect(longhands);
    let invalid_rect = rect(invalid);
    let important_rect = rect(important);
    assert_eq!(
        reset_rect,
        NativeRect {
            x: 0,
            y: 0,
            width: 4,
            height: 4
        }
    );
    assert_eq!(
        longhands_rect,
        NativeRect {
            x: 6,
            y: 0,
            width: 4,
            height: 4
        }
    );
    assert_eq!(
        invalid_rect,
        NativeRect {
            x: 12,
            y: 0,
            width: 8,
            height: 4
        }
    );
    assert_eq!(
        important_rect,
        NativeRect {
            x: 22,
            y: 0,
            width: 10,
            height: 4
        }
    );

    let list = document.display_list(viewport).unwrap();
    for (node_id, rect, color) in [
        (reset, reset_rect, NativeColor::RED),
        (
            longhands,
            longhands_rect,
            NativeColor {
                red: 0,
                green: 128,
                blue: 0,
                alpha: u8::MAX,
            },
        ),
        (
            invalid,
            invalid_rect,
            NativeColor {
                red: 0,
                green: 0,
                blue: u8::MAX,
                alpha: u8::MAX,
            },
        ),
        (important, important_rect, NativeColor::BLACK),
    ] {
        assert!(list.commands.iter().any(|command| {
            matches!(
                command,
                NativeDisplayCommand::FillRect { node_id: command_node, rect: command_rect, color: command_color, .. }
                    if *command_node == node_id && *command_rect == rect && *command_color == color
            )
        }));
    }
    assert_eq!(layout.hit_test(1, 1).unwrap(), Some(reset));
    assert_eq!(layout.hit_test(23, 1).unwrap(), Some(important));
    let surface = list.rasterize().unwrap();
    assert_eq!(surface.pixel(1, 1), Some([255, 0, 0, 255]));
    assert_eq!(surface.pixel(23, 1), Some([0, 0, 0, 255]));
    assert!(!surface.to_png().unwrap().is_empty());
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue && diagnostic.detail == "flex"
    }));
}

#[test]
fn native_flex_flow_css_wide_resets_reach_layout_and_raster() {
    let document = NativeDocument::parse(
        "<style>.flex { display:flex; width:8px; height:8px; gap:2px; align-items:flex-start; } .item { width:4px; height:4px; flex-shrink:0; } #direction { flex-direction:column; } #direction { flex-direction:INITIAL; } #wrap { flex-wrap:wrap; } #wrap { flex-wrap:UNSET; } #flow { flex-flow:column wrap; } #flow { flex-flow:ReVeRt; } #invalid { flex-flow:row-reverse wrap; } #invalid { flex-flow:inherit row; } #important { flex-flow:column wrap !important; } #important { flex-flow:initial; }</style><div id='direction' class='flex'><button id='direction-first' class='item' style='background-color:red'>A</button><button id='direction-second' class='item' style='background-color:blue'>B</button></div><div id='wrap' class='flex'><div id='wrap-first' class='item' style='background-color:red'>A</div><div id='wrap-second' class='item' style='background-color:blue'>B</div></div><div id='flow' class='flex'><div id='flow-first' class='item' style='background-color:red'>A</div><div id='flow-second' class='item' style='background-color:blue'>B</div></div><div id='invalid' class='flex'><div id='invalid-first' class='item' style='background-color:green'>A</div><div id='invalid-second' class='item' style='background-color:black'>B</div></div><div id='important' class='flex'><div id='important-first' class='item' style='background-color:red'>A</div><div id='important-second' class='item' style='background-color:blue'>B</div></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 24,
        height: 48,
        device_scale_factor_milli: 1000,
    };
    let direction = document.resolve_target("id=direction").unwrap();
    let direction_first = document.resolve_target("id=direction-first").unwrap();
    let direction_second = document.resolve_target("id=direction-second").unwrap();
    let wrap = document.resolve_target("id=wrap").unwrap();
    let wrap_first = document.resolve_target("id=wrap-first").unwrap();
    let wrap_second = document.resolve_target("id=wrap-second").unwrap();
    let flow = document.resolve_target("id=flow").unwrap();
    let flow_first = document.resolve_target("id=flow-first").unwrap();
    let flow_second = document.resolve_target("id=flow-second").unwrap();
    let invalid_first = document.resolve_target("id=invalid-first").unwrap();
    let invalid_second = document.resolve_target("id=invalid-second").unwrap();
    let important = document.resolve_target("id=important").unwrap();
    let important_first = document.resolve_target("id=important-first").unwrap();
    let important_second = document.resolve_target("id=important-second").unwrap();

    let layout = document.layout(viewport).unwrap();
    let rect = |node_id| layout.box_for(node_id).expect("layout rectangle");
    let direction_rect = rect(direction);
    let direction_first_rect = rect(direction_first);
    let direction_second_rect = rect(direction_second);
    assert_eq!(direction_rect.width, 8);
    assert_eq!(direction_rect.height, 8);
    assert_eq!(direction_first_rect.x, direction_rect.x);
    assert_eq!(direction_second_rect.x, direction_rect.x + 6);
    assert_eq!(direction_second_rect.y, direction_first_rect.y);

    let wrap_rect = rect(wrap);
    let wrap_first_rect = rect(wrap_first);
    let wrap_second_rect = rect(wrap_second);
    assert_eq!(wrap_second_rect.x, wrap_rect.x + 6);
    assert_eq!(wrap_second_rect.y, wrap_first_rect.y);

    let flow_rect = rect(flow);
    let flow_first_rect = rect(flow_first);
    let flow_second_rect = rect(flow_second);
    assert_eq!(flow_second_rect.x, flow_rect.x + 6);
    assert_eq!(flow_second_rect.y, flow_first_rect.y);

    let invalid_first_rect = rect(invalid_first);
    let invalid_second_rect = rect(invalid_second);
    assert!(invalid_second_rect.y > invalid_first_rect.y);

    let important_rect = rect(important);
    let important_first_rect = rect(important_first);
    let important_second_rect = rect(important_second);
    assert_eq!(important_second_rect.x, important_rect.x + 6);
    assert_eq!(important_second_rect.y, important_first_rect.y);

    let semantic_nodes = document.semantic_nodes();
    assert!(
        semantic_nodes
            .iter()
            .position(|semantic_node| semantic_node.node_id == direction_first)
            < semantic_nodes
                .iter()
                .position(|semantic_node| semantic_node.node_id == direction_second)
    );

    let list = document.display_list(viewport).unwrap();
    let surface = list.rasterize().unwrap();
    for (node_id, node_rect, color) in [
        (direction_first, direction_first_rect, [255, 0, 0, 255]),
        (direction_second, direction_second_rect, [0, 0, 255, 255]),
        (invalid_first, invalid_first_rect, [0, 128, 0, 255]),
        (invalid_second, invalid_second_rect, [0, 0, 0, 255]),
    ] {
        assert!(list.commands.iter().any(|command| {
            matches!(
                command,
                NativeDisplayCommand::FillRect { node_id: command_node, rect: command_rect, .. }
                    if *command_node == node_id && *command_rect == node_rect
            )
        }));
        assert_eq!(surface.pixel(node_rect.x + 1, node_rect.y + 1), Some(color));
    }
    assert_eq!(
        layout
            .hit_test(
                i64::from(direction_first_rect.x + 1),
                i64::from(direction_first_rect.y + 1),
            )
            .unwrap(),
        Some(direction_first)
    );
    assert_eq!(
        layout
            .hit_test(
                i64::from(important_second_rect.x + 1),
                i64::from(important_second_rect.y + 1),
            )
            .unwrap(),
        Some(important_second)
    );
    assert!(!surface.to_png().unwrap().is_empty());
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && diagnostic.detail == "flex-flow"
    }));
}

#[test]
fn native_flex_flow_shorthand_reuses_reverse_and_wrap_consumers() {
    let document = NativeDocument::parse(
        "<div id='row' style='display:flex;width:12px;gap:2px;flex-flow:row-reverse wrap'><div id='first' style='width:8px;height:6px;margin:1px;flex-shrink:0;background-color:red'>A</div><div id='second' style='width:4px;height:6px;margin:1px;flex-shrink:0;background-color:blue'>B</div></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let row = document.resolve_target("id=row").unwrap();
    let first = document.resolve_target("id=first").unwrap();
    let second = document.resolve_target("id=second").unwrap();
    let viewport = Viewport {
        width: 16,
        height: 24,
        device_scale_factor_milli: 1000,
    };
    let layout = document.layout(viewport).unwrap();

    assert_eq!(layout.box_for(row).unwrap().width, 12);
    assert_eq!(
        layout.box_for(first),
        Some(NativeRect {
            x: 3,
            y: 1,
            width: 8,
            height: 6,
        })
    );
    assert_eq!(
        layout.box_for(second),
        Some(NativeRect {
            x: 7,
            y: 11,
            width: 4,
            height: 6,
        })
    );

    let list = document.display_list(viewport).unwrap();
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, rect, color, .. }
                if *node_id == first && rect.x == 3 && rect.y == 1 && *color == NativeColor::RED
        )
    }));
    assert_eq!(layout.hit_test(4, 2).unwrap(), Some(first));
    assert_eq!(layout.hit_test(8, 12).unwrap(), Some(second));
}

#[tokio::test]
async fn legacy_name_fragments_use_decoded_fallback_and_preserve_scroll_safety() {
    let html = "<a id='jump' href='#legacy%20plan'>Jump</a><p>one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen</p><p>seventeen eighteen nineteen twenty twenty-one twenty-two twenty-three twenty-four twenty-five twenty-six</p><a name='legacy plan'>Legacy target</a><a name='café'>UTF-8 legacy target</a><a name='same'>Name should lose</a><a name='hidden' style='display:none'>Hidden legacy target</a><a name='zero' style='display:contents'></a><a name='duplicate'>First duplicate</a><a name='duplicate'>Second duplicate</a><div name='not-anchor'>Not a target</div><p id='same'>ID target</p>";
    let viewport = Viewport {
        width: 160,
        height: 40,
        device_scale_factor_milli: 1000,
    };
    let expected_document = NativeDocument::parse(html, &NativeEngineLimits::default()).unwrap();
    let expected_layout = expected_document.layout(viewport).unwrap();
    let legacy = find_element_with_attribute(&expected_document, "a", "name", "legacy plan");
    let legacy_scroll = NativePoint {
        x: 0,
        y: expected_layout
            .box_for(legacy)
            .expect("legacy anchor layout")
            .y
            .min(expected_layout.max_scroll_offset().y),
    };
    assert!(legacy_scroll.y > 0);

    let config = NativeEngineConfig::default()
        .with_viewport(viewport)
        .with_fixture("fixture://name-fragments", html)
        .unwrap()
        .with_initial_url("fixture://name-fragments");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    let jumped = engine
        .action(NativeAction::Click {
            target: "id=jump".into(),
        })
        .unwrap();
    assert!(jumped.accepted);
    assert_eq!(engine.scroll_offset(), legacy_scroll);
    assert_eq!(
        engine.snapshot().unwrap().url,
        "fixture://name-fragments#legacy%20plan"
    );

    let initial = engine.go_back().unwrap().unwrap();
    assert_eq!(initial.url, "fixture://name-fragments");
    assert_eq!(engine.scroll_offset(), NativePoint { x: 0, y: 0 });
    let restored = engine.go_forward().unwrap().unwrap();
    assert_eq!(restored.url, "fixture://name-fragments#legacy%20plan");
    assert_eq!(engine.scroll_offset(), legacy_scroll);

    engine
        .navigate("fixture://name-fragments#caf%C3%A9")
        .unwrap();
    let utf8_target = find_element_with_attribute(&expected_document, "a", "name", "café");
    assert_eq!(
        engine.scroll_offset().y,
        expected_layout
            .box_for(utf8_target)
            .unwrap()
            .y
            .min(expected_layout.max_scroll_offset().y)
    );

    engine.navigate("fixture://name-fragments#same").unwrap();
    let id_target = expected_document.resolve_target("id=same").unwrap();
    assert_eq!(
        engine.scroll_offset().y,
        expected_layout
            .box_for(id_target)
            .unwrap()
            .y
            .min(expected_layout.max_scroll_offset().y)
    );
    for fragment in [
        "duplicate",
        "not-anchor",
        "DUPLICATE",
        "hidden",
        "zero",
        "missing",
    ] {
        let before = engine.scroll_offset();
        engine
            .navigate(format!("fixture://name-fragments#{fragment}"))
            .unwrap();
        assert_eq!(engine.scroll_offset(), before, "fragment={fragment}");
    }
}

