#[test]
fn native_css_diagnostics_are_bounded() {
    let mut source = String::from("<style>");
    for index in 0..MAX_NATIVE_DIAGNOSTICS.saturating_add(8) {
        source.push_str(&format!(".item{index} {{ unknown-{index}: value; }}"));
    }
    source.push_str("</style><div class='item0'>Item</div>");

    let document = NativeDocument::parse(&source, &NativeEngineLimits::default()).unwrap();
    assert_eq!(document.diagnostics().len(), MAX_NATIVE_DIAGNOSTICS);
    assert!(document.diagnostics_truncated());
}

#[test]
fn native_css_diagnostics_replace_atomically_with_navigation() {
    let config = NativeEngineConfig::default()
        .with_fixture(
            "fixture://diagnostic-bad",
            "<style>#card { width: 50%; }</style><div id='card'>Bad</div>",
        )
        .unwrap()
        .with_fixture("fixture://diagnostic-good", "<div id='card'>Good</div>")
        .unwrap()
        .with_initial_url("fixture://diagnostic-bad");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    let initial = engine.diagnostics().unwrap();
    assert_eq!(initial.revision, 1);
    assert_eq!(initial.diagnostics.len(), 1);
    assert!(!initial.truncated);

    let failed = engine.navigate("fixture://missing");
    assert!(matches!(
        failed,
        Err(NativeEngineError::UnsupportedUrl { .. })
    ));
    let after_failure = engine.diagnostics().unwrap();
    assert_eq!(after_failure, initial);

    engine.navigate("fixture://diagnostic-good").unwrap();
    let after_success = engine.diagnostics().unwrap();
    assert_eq!(after_success.revision, 2);
    assert!(after_success.diagnostics.is_empty());
    assert!(!after_success.truncated);
}

#[tokio::test]
async fn native_content_process_fetches_cors_authorized_cross_origin_get() {
    let _guard = native_content_process_test_lock().lock().await;
    let document_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let document_address = document_listener.local_addr().unwrap();
    let api_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let api_address = api_listener.local_addr().unwrap();
    let document_origin = format!("http://{document_address}");
    let expected_origin = document_origin.clone();
    let response_origin = document_origin.clone();

    let document_server = tokio::spawn(async move {
        let (mut stream, _) = document_listener.accept().await.unwrap();
        let mut request = [0_u8; 4096];
        let _ = stream.read(&mut request).await.unwrap();
        let body = "<title>Fetch owner</title><p>Native fetch</p>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Security-Policy: connect-src *\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });
    let api_server = tokio::spawn(async move {
        let (mut stream, _) = api_listener.accept().await.unwrap();
        let mut request = [0_u8; 4096];
        let read = stream.read(&mut request).await.unwrap();
        let request = String::from_utf8_lossy(&request[..read]);
        assert_eq!(request.split_whitespace().nth(1), Some("/data"));
        assert!(
            request.lines().any(|line| {
                line.split_once(':').is_some_and(|(name, value)| {
                    name.eq_ignore_ascii_case("origin") && value.trim() == expected_origin
                })
            }),
            "cross-origin fetch omitted its Origin header: {request}"
        );
        let body = "{\"ok\":true}";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nAccess-Control-Allow-Origin: {response_origin}\r\nAccess-Control-Expose-Headers: X-Visible\r\nX-Visible: yes\r\nX-Hidden: no\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("{document_origin}/index.html")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    let response = engine
        .fetch_async(format!("http://{api_address}/data"), false)
        .await
        .unwrap();
    assert_eq!(response.status, 200);
    assert_eq!(response.content_type.as_deref(), Some("application/json"));
    let mut headers = response.headers.clone();
    headers.sort();
    assert_eq!(
        headers,
        vec![
            ("content-length".into(), "11".into()),
            ("content-type".into(), "application/json".into()),
            ("x-visible".into(), "yes".into()),
        ]
    );
    assert_eq!(response.body, br#"{"ok":true}"#);
    engine.close_async().await.unwrap();
    document_server.await.unwrap();
    api_server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_fetches_cross_origin_post_after_cors_preflight() {
    let _guard = native_content_process_test_lock().lock().await;
    let document_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let document_address = document_listener.local_addr().unwrap();
    let api_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let api_address = api_listener.local_addr().unwrap();
    let document_origin = format!("http://{document_address}");
    let expected_origin = document_origin.clone();
    let response_origin = document_origin.clone();

    let document_server = tokio::spawn(async move {
        let (mut stream, _) = document_listener.accept().await.unwrap();
        let _request = read_http_request(&mut stream).await;
        let body = "<title>Fetch owner</title><p>Native fetch</p>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Security-Policy: connect-src *\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });
    let api_server = tokio::spawn(async move {
        let (mut stream, _) = api_listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().next(), Some("OPTIONS"));
        assert_eq!(request.split_whitespace().nth(1), Some("/submit"));
        assert!(request.lines().any(|line| {
            line.split_once(':').is_some_and(|(name, value)| {
                name.eq_ignore_ascii_case("origin") && value.trim() == expected_origin
            })
        }));
        assert!(request.lines().any(|line| {
            line.split_once(':').is_some_and(|(name, value)| {
                name.eq_ignore_ascii_case("access-control-request-method") && value.trim() == "POST"
            })
        }));
        assert!(request.lines().any(|line| {
            line.split_once(':').is_some_and(|(name, value)| {
                name.eq_ignore_ascii_case("access-control-request-headers")
                    && value
                        .trim()
                        .eq_ignore_ascii_case("content-type, x-glass-token")
            })
        }));
        let response = format!(
            "HTTP/1.1 204 No Content\r\nAccess-Control-Allow-Origin: {response_origin}\r\nAccess-Control-Allow-Methods: POST\r\nAccess-Control-Allow-Headers: content-type, x-glass-token\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
        );
        stream.write_all(response.as_bytes()).await.unwrap();

        let (mut stream, _) = api_listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().next(), Some("POST"));
        assert_eq!(request.split_whitespace().nth(1), Some("/submit"));
        assert!(request.lines().any(|line| {
            line.split_once(':').is_some_and(|(name, value)| {
                name.eq_ignore_ascii_case("origin") && value.trim() == expected_origin
            })
        }));
        assert!(request.lines().any(|line| {
            line.split_once(':').is_some_and(|(name, value)| {
                name.eq_ignore_ascii_case("x-glass-token") && value.trim() == "alpha"
            })
        }));
        let body = request
            .split_once("\r\n\r\n")
            .map(|(_, body)| body)
            .unwrap_or_default();
        assert_eq!(body, r#"{"name":"glass"}"#);
        let body = "{\"value\":\"cors-posted\"}";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nAccess-Control-Allow-Origin: {response_origin}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("{document_origin}/index.html")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(&format!(
            "fetch('http://{api_address}/submit', {{ method: 'POST', credentials: 'omit', body: '{{\"name\":\"glass\"}}', headers: {{ 'Content-Type': 'application/json', 'X-Glass-Token': 'alpha' }} }}).then(response => response.json()).then(data => {{ globalThis.corsPostFetchValue = data.value; }});"
        ))
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.corsPostFetchValue")
            .await
            .unwrap(),
        serde_json::json!("cors-posted")
    );
    engine.close_async().await.unwrap();
    document_server.await.unwrap();
    api_server.await.unwrap();
}

