#[tokio::test]
async fn native_content_process_fetches_common_http_methods_with_cors_preflight() {
    let _guard = native_content_process_test_lock().lock().await;
    let document_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let document_address = document_listener.local_addr().unwrap();
    let api_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let api_address = api_listener.local_addr().unwrap();
    let document_origin = format!("http://{document_address}");
    let response_origin = document_origin.clone();

    let document_server = tokio::spawn(async move {
        let (mut stream, _) = document_listener.accept().await.unwrap();
        let _request = read_http_request(&mut stream).await;
        let body = "<title>Fetch methods</title><p>Native fetch</p>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Security-Policy: connect-src *\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });
    let api_server = tokio::spawn(async move {
        for _ in 0..9 {
            let (mut stream, _) = api_listener.accept().await.unwrap();
            let request = read_http_request(&mut stream).await;
            let method = request.split_whitespace().next().unwrap_or_default();
            let is_preflight = method == "OPTIONS"
                && request.lines().any(|line| {
                    line.split_once(':').is_some_and(|(name, _)| {
                        name.eq_ignore_ascii_case("access-control-request-method")
                    })
                });
            if is_preflight {
                assert!(request.lines().any(|line| {
                    line.split_once(':').is_some_and(|(name, value)| {
                        name.eq_ignore_ascii_case("access-control-request-method")
                            && ["PUT", "PATCH", "DELETE", "OPTIONS"].contains(&value.trim())
                    })
                }));
                let response = format!(
                    "HTTP/1.1 204 No Content\r\nAccess-Control-Allow-Origin: {response_origin}\r\nAccess-Control-Allow-Methods: HEAD, PUT, PATCH, DELETE, OPTIONS\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
                );
                stream.write_all(response.as_bytes()).await.unwrap();
                continue;
            }
            assert_eq!(request.split_whitespace().nth(1), Some("/methods"));
            assert!(matches!(
                method,
                "HEAD" | "PUT" | "PATCH" | "DELETE" | "OPTIONS"
            ));
            let request_body = request
                .split_once("\r\n\r\n")
                .map(|(_, body)| body)
                .unwrap_or_default();
            if method == "HEAD" {
                assert!(request_body.is_empty());
            } else {
                assert_eq!(request_body, method);
            }
            let body = if method == "HEAD" { "" } else { method };
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nAccess-Control-Allow-Origin: {response_origin}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
            if !body.is_empty() {
                stream.write_all(body.as_bytes()).await.unwrap();
            }
        }
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("{document_origin}/index.html")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    for method in ["HEAD", "PUT", "PATCH", "DELETE", "OPTIONS"] {
        let body = if method == "HEAD" {
            "undefined".to_owned()
        } else {
            format!("'{method}'")
        };
        let result = engine
            .evaluate_async(&format!(
                "await (async () => {{ const response = await fetch('http://{api_address}/methods', {{ method: '{method}', credentials: 'omit', body: {body} }}); return [response.status, await response.text()]; }})()"
            ))
            .await
            .unwrap();
        assert_eq!(
            result,
            serde_json::json!([200, if method == "HEAD" { "" } else { method }])
        );
    }
    engine.close_async().await.unwrap();
    document_server.await.unwrap();
    api_server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_exposes_opaque_no_cors_response() {
    let _guard = native_content_process_test_lock().lock().await;
    let document_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let document_address = document_listener.local_addr().unwrap();
    let api_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let api_address = api_listener.local_addr().unwrap();
    let document_origin = format!("http://{document_address}");

    let document_server = tokio::spawn(async move {
        let (mut stream, _) = document_listener.accept().await.unwrap();
        let _request = read_http_request(&mut stream).await;
        let body = "<title>Fetch owner</title><p>Native fetch</p>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Security-Policy: connect-src *\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });
    let api_server = tokio::spawn(async move {
        let (mut stream, _) = api_listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().next(), Some("GET"));
        assert_eq!(request.split_whitespace().nth(1), Some("/opaque"));
        assert!(!request.lines().any(|line| {
            line.split_once(':')
                .is_some_and(|(name, _)| name.eq_ignore_ascii_case("origin"))
        }));
        let body = "secret cross-origin body";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nX-Private: hidden\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("{document_origin}/index.html")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(&format!(
            "fetch('http://{api_address}/opaque', {{ mode: 'same-origin' }}).then(() => {{ globalThis.sameOriginModeValue = ['fulfilled', false]; }}, error => {{ globalThis.sameOriginModeValue = [error.name, error.message.includes('different origin')]; }});"
        ))
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.sameOriginModeValue")
            .await
            .unwrap(),
        serde_json::json!(["Error", true])
    );
    engine
        .evaluate_async(&format!(
            "fetch('http://{api_address}/opaque', {{ mode: 'no-cors', headers: {{ 'X-Not-Safelisted': 'blocked' }} }}).then(() => {{ globalThis.noCorsHeaderValue = ['fulfilled', false]; }}, error => {{ globalThis.noCorsHeaderValue = [error.name, error.message.includes('non-safelisted')]; }});"
        ))
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.noCorsHeaderValue")
            .await
            .unwrap(),
        serde_json::json!(["Error", true])
    );
    engine
        .evaluate_async(&format!(
            "fetch('http://{api_address}/opaque', {{ mode: 'no-cors', credentials: 'omit' }}).then(async response => {{ const bodyRead = await response.text().then(() => 'readable', error => error.name); globalThis.opaqueFetchValue = [response.type, response.status, response.ok, response.url, Array.from(response.headers.entries()), bodyRead, response.body === null]; }});"
        ))
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.opaqueFetchValue")
            .await
            .unwrap(),
        serde_json::json!(["opaque", 0, false, "", [], "TypeError", true])
    );
    engine.close_async().await.unwrap();
    document_server.await.unwrap();
    api_server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_fetches_bounded_redirect_modes() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let cross_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let cross_address = cross_listener.local_addr().unwrap();
    let cross_server = tokio::spawn(async move {
        let accepted =
            tokio::time::timeout(Duration::from_millis(500), cross_listener.accept()).await;
        assert!(
            accepted.is_err(),
            "same-origin redirect reached the new origin"
        );
    });
    let server = tokio::spawn(async move {
        for expected_path in ["/page", "/follow", "/final", "/cross", "/error", "/manual"] {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request = read_http_request(&mut stream).await;
            assert_eq!(request.split_whitespace().nth(1), Some(expected_path));
            let response = match expected_path {
                "/page" => {
                    let body = "<title>Fetch owner</title><p>Native fetch</p>";
                    format!(
                        "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Security-Policy: connect-src *\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                        body.len()
                    )
                }
                "/follow" => {
                    "HTTP/1.1 302 Found\r\nLocation: /final\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
                        .to_owned()
                }
                "/error" => {
                    "HTTP/1.1 302 Found\r\nLocation: /error-final\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
                        .to_owned()
                }
                "/cross" => format!(
                    "HTTP/1.1 302 Found\r\nLocation: http://{cross_address}/final\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
                ),
                "/manual" => {
                    "HTTP/1.1 302 Found\r\nLocation: /manual-final\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
                        .to_owned()
                }
                "/final" => {
                    let body = "redirected-final";
                    format!(
                        "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                        body.len()
                    )
                }
                _ => unreachable!(),
            };
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            "fetch('/not-requested', { redirect: 'invalid' }).then(() => { globalThis.invalidRedirectValue = ['fulfilled', false]; }, error => { globalThis.invalidRedirectValue = [error.name, error.message.includes('redirect mode')]; });",
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.invalidRedirectValue")
            .await
            .unwrap(),
        serde_json::json!(["TypeError", true])
    );
    engine
        .evaluate_async(
            "fetch('/follow').then(async response => { globalThis.followRedirectValue = [response.type, response.redirected, response.status, response.url, await response.text()]; });",
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.followRedirectValue")
            .await
            .unwrap(),
        serde_json::json!([
            "basic",
            true,
            200,
            format!("http://{address}/final"),
            "redirected-final"
        ])
    );
    engine
        .evaluate_async(
            "fetch('/cross', { mode: 'same-origin' }).then(() => { globalThis.crossOriginRedirectValue = ['fulfilled', false]; }, error => { globalThis.crossOriginRedirectValue = [error.name, error.message.includes('different origin')]; });",
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.crossOriginRedirectValue")
            .await
            .unwrap(),
        serde_json::json!(["Error", true])
    );
    engine
        .evaluate_async(
            "fetch('/error', { redirect: 'error' }).then(() => { globalThis.errorRedirectValue = ['fulfilled', false]; }, error => { globalThis.errorRedirectValue = [error.name, error.message.includes('disallowed')]; });",
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.errorRedirectValue")
            .await
            .unwrap(),
        serde_json::json!(["Error", true])
    );
    engine
        .evaluate_async(
            "fetch('/manual', { redirect: 'manual' }).then(async response => { const body = await response.text().then(() => 'readable', error => error.name); globalThis.manualRedirectValue = [response.type, response.redirected, response.status, response.url, Array.from(response.headers.entries()), body]; });",
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.manualRedirectValue")
            .await
            .unwrap(),
        serde_json::json!(["opaqueredirect", false, 0, "", [], "TypeError"])
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
    cross_server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_exposes_bounded_script_fetch_promises() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for expected_path in [
            "/page",
            "/headers",
            "/data",
            "/binary",
            "/upload",
            "/constructed-upload",
            "/file-upload",
            "/form-upload",
            "/data",
        ] {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request_bytes = read_http_request_bytes(&mut stream).await;
            let request = String::from_utf8_lossy(&request_bytes);
            assert_eq!(request.split_whitespace().nth(1), Some(expected_path));
            if expected_path == "/data" {
                assert!(request.lines().any(|line| {
                    line.split_once(':').is_some_and(|(name, value)| {
                        name.eq_ignore_ascii_case("x-glass-token") && value.trim() == "alpha"
                    })
                }));
            }
            if expected_path == "/headers" {
                assert!(request.lines().any(|line| {
                    line.split_once(':').is_some_and(|(name, value)| {
                        name.eq_ignore_ascii_case("x-glass-token") && value.trim() == "alpha, beta"
                    })
                }));
            }
            if matches!(
                expected_path,
                "/upload" | "/constructed-upload" | "/file-upload"
            ) {
                let header_end = request_bytes
                    .windows(4)
                    .position(|window| window == b"\r\n\r\n")
                    .unwrap()
                    + 4;
                assert!(request.lines().any(|line| {
                    line.split_once(':').is_some_and(|(name, value)| {
                        name.eq_ignore_ascii_case("content-type")
                            && value.trim() == "application/octet-stream"
                    })
                }));
                assert_eq!(&request_bytes[header_end..], [0_u8, 0xff, 0x80, b'A']);
            }
            if expected_path == "/form-upload" {
                assert!(request.lines().any(|line| {
                    line.split_once(':').is_some_and(|(name, value)| {
                        name.eq_ignore_ascii_case("content-type")
                            && value
                                .trim()
                                .starts_with("multipart/form-data; boundary=----GlassNativeForm")
                    })
                }));
                let header_end = request_bytes
                    .windows(4)
                    .position(|window| window == b"\r\n\r\n")
                    .unwrap()
                    + 4;
                let body = &request_bytes[header_end..];
                assert!(
                    body.windows(b"name=\"name\"".len())
                        .any(|window| window == b"name=\"name\"")
                );
                assert!(
                    body.windows(b"name=\"payload\"".len())
                        .any(|window| window == b"name=\"payload\"")
                );
                assert!(
                    body.windows([0_u8, 0xff, 0x80, b'A'].len())
                        .any(|window| window == [0_u8, 0xff, 0x80, b'A'])
                );
            }
            if expected_path == "/binary" {
                let body = [0_u8, 0xff, 0x80, b'A'];
                let response = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                    body.len()
                );
                stream.write_all(response.as_bytes()).await.unwrap();
                stream.write_all(&body).await.unwrap();
                continue;
            }
            let (content_type, body) = if expected_path == "/page" {
                ("text/html", "<input id='result' value='pending'>")
            } else if expected_path == "/headers" {
                ("text/plain", "headers-ok")
            } else if expected_path.ends_with("upload") {
                ("text/plain", "uploaded")
            } else {
                ("application/json", "{\"value\":\"fetched\"}")
            };
            let extra_headers = if expected_path == "/data" {
                "X-Glass-Response: one\r\nX-Glass-Response: two\r\n"
            } else {
                ""
            };
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\n{extra_headers}Content-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            "(() => { const headers = new Headers([['X-Glass-Token', 'alpha']]); headers.append('x-glass-token', 'beta'); headers.set('X-Glass-Extra', 'gamma'); headers.delete('x-glass-extra'); const endpoint = new URL('/headers', location.href); const query = new URL('?source=request#part', endpoint.href); const nested = new URL('../target?x=one#frag', 'http://example.test/a/b/page'); const protocolRelative = new URL('//api.example.test/v1', endpoint.href); const mutable = new URL('/headers?old=one', location.href); mutable.pathname = '/changed/../final'; mutable.searchParams.set('old', 'two'); mutable.searchParams.append('z', '3'); mutable.hash = 'changed'; const replacement = new URL('/headers?reset=yes#next', location.href); replacement.href = '/headers?reset=updated#final'; const authority = new URL('http://user:pass@api.example.test:8080/start', location.href); authority.protocol = 'https'; authority.hostname = 'other.example.test'; authority.port = '8443'; authority.username = 'next user'; authority.password = 'secret'; authority.host = 'final.example.test:9443'; const authorityBeforeInvalid = authority.href; const authorityErrors = []; try { authority.protocol = 'ftp'; } catch (error) { authorityErrors.push(error.name); } try { authority.host = 'bad/path'; } catch (error) { authorityErrors.push(error.name); } try { authority.port = '65536'; } catch (error) { authorityErrors.push(error.name); } globalThis.urlAuthorityView = [authority.protocol, authority.username, authority.password, authority.host, authority.hostname, authority.port, authority.href, authority.origin]; globalThis.urlAuthorityInvalid = [authorityErrors, authority.href === authorityBeforeInvalid]; const request = new Request(endpoint, { headers }); const requestClone = request.clone(); globalThis.urlObjectView = [endpoint instanceof URL, endpoint.origin === location.origin, endpoint.pathname, endpoint.search, endpoint.hash, query.searchParams.get('source'), query.hash, nested.pathname, nested.searchParams.get('x'), nested.hash, protocolRelative.origin, protocolRelative.pathname, mutable.pathname, mutable.search, mutable.searchParams.get('old'), mutable.href.endsWith('/final?old=two&z=3#changed'), replacement.href.endsWith('/headers?reset=updated#final'), replacement.searchParams.get('reset'), replacement.hash]; globalThis.requestObjectView = [request instanceof Request, request.method, request.url === endpoint.href, request.mode, request.redirect, request.headers.get('x-glass-token'), requestClone.headers.get('x-glass-token'), requestClone !== request]; globalThis.requestHeaderView = [headers.get('x-glass-token'), headers.has('X-Glass-Token'), Array.from(headers.entries()), Array.from(headers.keys()), Array.from(headers.values()), headers.size]; fetch(requestClone).then(response => response.text()).then(value => { globalThis.headerFetch = value; }); })()",
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.requestHeaderView")
            .await
            .unwrap(),
        serde_json::json!([
            "alpha, beta",
            true,
            [["x-glass-token", "alpha, beta"]],
            ["x-glass-token"],
            ["alpha, beta"],
            1
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.requestObjectView")
            .await
            .unwrap(),
        serde_json::json!([
            true,
            "GET",
            true,
            "cors",
            "follow",
            "alpha, beta",
            "alpha, beta",
            true,
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.urlObjectView")
            .await
            .unwrap(),
        serde_json::json!([
            true,
            true,
            "/headers",
            "",
            "",
            "request",
            "#part",
            "/a/target",
            "one",
            "#frag",
            "http://api.example.test",
            "/v1",
            "/final",
            "?old=two&z=3",
            "two",
            true,
            true,
            "updated",
            "#final",
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.urlAuthorityView")
            .await
            .unwrap(),
        serde_json::json!([
            "https:",
            "next%20user",
            "secret",
            "final.example.test:9443",
            "final.example.test",
            "9443",
            "https://next%20user:secret@final.example.test:9443/start",
            "https://final.example.test:9443",
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.urlAuthorityInvalid")
            .await
            .unwrap(),
        serde_json::json!([["TypeError", "TypeError", "TypeError"], true])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.headerFetch")
            .await
            .unwrap(),
        serde_json::json!("headers-ok")
    );
    engine
        .evaluate_async(
            "fetch('/data', { headers: { 'X-Glass-Token': 'alpha' } }).then(async response => { const headerEvents = []; response.headers.forEach((value, name) => headerEvents.push(name + '=' + value)); const clonedResponse = response.clone(); const jsonResponse = response.clone(); const textResponse = response.clone(); const blobResponse = response.clone(); const bufferResponse = response.clone(); const bytesResponse = response.clone(); const stream = response.body; const streamReader = stream.getReader(); const streamFirst = await streamReader.read(); const streamSecond = await streamReader.read(); const streamLocked = stream.locked; streamReader.releaseLock(); const releasedStreamRead = await streamReader.read().then(() => 'readable', error => error.name); const clonedText = await clonedResponse.text(); globalThis.fetchClone = [clonedText, clonedResponse.body instanceof ReadableStream, clonedResponse.body !== response.body]; globalThis.fetchStream = [response.body instanceof ReadableStream, streamLocked, stream.locked, streamFirst.done, Array.from(streamFirst.value), streamSecond.done, releasedStreamRead]; globalThis.fetchHeaders = [response.headers.get('CONTENT-TYPE'), response.headers.has('content-type'), Array.from(response.headers.entries()), Array.from(response.headers.keys()), Array.from(response.headers.values()), Array.from(response.headers), headerEvents]; return Promise.all([jsonResponse.json(), textResponse.text(), blobResponse.blob(), bufferResponse.arrayBuffer(), bytesResponse.bytes()]); }).then(async ([data, text, blob, buffer, bytes]) => { globalThis.fetchValue = data.value; globalThis.fetchBody = [text, blob instanceof Blob, buffer instanceof ArrayBuffer && Array.from(new Uint8Array(buffer)), Array.from(bytes), await blob.text()]; const binaryResponse = await fetch('/binary'); const binaryBufferResponse = binaryResponse.clone(); const binaryBytesResponse = binaryResponse.clone(); const binaryBlobResponse = binaryResponse.clone(); const binaryStream = binaryResponse.body; const binaryReader = binaryStream.getReader(); const binaryLocked = binaryStream.locked; await binaryReader.cancel(); binaryReader.releaseLock(); const canceledReader = binaryStream.getReader(); const canceledChunk = await canceledReader.read(); canceledReader.releaseLock(); globalThis.fetchStream = globalThis.fetchStream.concat([binaryResponse.body instanceof ReadableStream, binaryLocked, canceledChunk.done, binaryStream.locked]); const binaryBuffer = await binaryBufferResponse.arrayBuffer(); const binaryBytes = await binaryBytesResponse.bytes(); const binaryBlob = await binaryBlobResponse.blob(); globalThis.binaryFetchBody = [Array.from(new Uint8Array(binaryBuffer)), Array.from(binaryBytes), binaryBlob.size, Array.from(await binaryBlob.slice(1, 3).bytes()), await binaryBlob.text()]; const uploadResponse = await fetch('/upload', { method: 'POST', body: binaryBlob, headers: { 'Content-Type': 'application/octet-stream' } }); globalThis.binaryUpload = await uploadResponse.text(); const payload = new Uint8Array([0, 255, 128, 65]); const constructedBlob = new Blob([payload], { type: 'application/octet-stream' }); const constructedFile = new File([payload.buffer], 'payload.bin', { type: 'application/octet-stream' }); globalThis.binaryConstruction = [constructedBlob.size, Array.from(await constructedBlob.bytes()), constructedFile.size, Array.from(await constructedFile.bytes())]; const constructedUpload = await fetch('/constructed-upload', { method: 'POST', body: constructedBlob }); const fileUpload = await fetch('/file-upload', { method: 'POST', body: constructedFile }); globalThis.binaryUploads = [await constructedUpload.text(), await fileUpload.text()]; const form = new FormData(); form.append('name', 'glass'); form.append('payload', binaryBlob, 'payload.bin'); const formUpload = await fetch('/form-upload', { method: 'POST', body: form }); globalThis.formUpload = await formUpload.text(); document.getElementById('result').value = data.value; const controller = new AbortController(); const events = []; controller.signal.addEventListener('abort', () => events.push('listener')); controller.signal.onabort = () => events.push('property'); const request = fetch('/data', { signal: controller.signal, headers: { 'X-Glass-Token': 'alpha' } }); controller.abort(); controller.abort(); request.catch(error => { globalThis.abortValue = [error.name, controller.signal.aborted, controller.signal.reason.name, events]; }); });",
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.fetchValue")
            .await
            .unwrap(),
        serde_json::json!("fetched")
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.abortValue")
            .await
            .unwrap(),
        serde_json::json!(["AbortError", true, "AbortError", ["listener", "property"]])
    );
    assert_eq!(
        engine.evaluate_async("globalThis.fetchBody").await.unwrap(),
        serde_json::json!([
            "{\"value\":\"fetched\"}",
            true,
            [
                123, 34, 118, 97, 108, 117, 101, 34, 58, 34, 102, 101, 116, 99, 104, 101, 100, 34,
                125
            ],
            [
                123, 34, 118, 97, 108, 117, 101, 34, 58, 34, 102, 101, 116, 99, 104, 101, 100, 34,
                125
            ],
            "{\"value\":\"fetched\"}",
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.fetchHeaders")
            .await
            .unwrap(),
        serde_json::json!([
            "application/json",
            true,
            [
                ["content-type", "application/json"],
                ["x-glass-response", "one, two"],
                ["content-length", "19"],
                ["connection", "close"]
            ],
            [
                "content-type",
                "x-glass-response",
                "content-length",
                "connection"
            ],
            ["application/json", "one, two", "19", "close"],
            [
                ["content-type", "application/json"],
                ["x-glass-response", "one, two"],
                ["content-length", "19"],
                ["connection", "close"]
            ],
            [
                "content-type=application/json",
                "x-glass-response=one, two",
                "content-length=19",
                "connection=close"
            ],
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.fetchStream")
            .await
            .unwrap(),
        serde_json::json!([
            true,
            true,
            false,
            false,
            [
                123, 34, 118, 97, 108, 117, 101, 34, 58, 34, 102, 101, 116, 99, 104, 101, 100, 34,
                125
            ],
            true,
            "TypeError",
            true,
            true,
            true,
            false,
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.fetchClone")
            .await
            .unwrap(),
        serde_json::json!(["{\"value\":\"fetched\"}", true, true])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.binaryFetchBody")
            .await
            .unwrap(),
        serde_json::json!([
            [0, 255, 128, 65],
            [0, 255, 128, 65],
            4,
            [255, 128],
            "\u{0}\u{fffd}\u{fffd}A",
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.binaryUpload")
            .await
            .unwrap(),
        serde_json::json!("uploaded")
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.binaryConstruction")
            .await
            .unwrap(),
        serde_json::json!([4, [0, 255, 128, 65], 4, [0, 255, 128, 65]])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.binaryUploads")
            .await
            .unwrap(),
        serde_json::json!(["uploaded", "uploaded"])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.formUpload")
            .await
            .unwrap(),
        serde_json::json!("uploaded")
    );
    engine
        .evaluate_async(
            "(() => { try { fetch('/data', { headers: { Cookie: 'secret' } }); } catch (error) { globalThis.forbiddenFetchHeader = [error.name, error.message]; } })()",
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.forbiddenFetchHeader")
            .await
            .unwrap(),
        serde_json::json!(["TypeError", "native fetch header is forbidden"])
    );
    assert_eq!(
        engine
            .evaluate_async("document.getElementById('result').value")
            .await
            .unwrap(),
        serde_json::json!("fetched")
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_exposes_page_web_storage_realm() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/page"));
        let body = "<p>Storage owner</p>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine
            .evaluate_async(
                "localStorage.setItem('theme', 'dark'); sessionStorage.setItem('tab', 'one'); ({ local: localStorage.getItem('theme'), session: sessionStorage.getItem('tab') })",
            )
            .await
            .unwrap(),
        serde_json::json!({"local":"dark","session":"one"})
    );
    assert_eq!(
        engine
            .evaluate_async("[localStorage.length, sessionStorage.length, localStorage.key(0), sessionStorage.key(0)]")
            .await
            .unwrap(),
        serde_json::json!([1, 1, "theme", "tab"])
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_indexed_db_round_trips_through_worker_ipc() {
    let _guard = native_content_process_test_lock().lock().await;
    let profile_path = std::env::temp_dir().join(format!(
        "glass-native-indexed-db-{}-content.json",
        std::process::id()
    ));
    let _ = fs::remove_file(&profile_path);
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/indexed-db"));
        let body = "<p>IndexedDB content owner</p>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default()
            .with_storage_path(profile_path.clone())
            .with_initial_url(format!("http://{address}/indexed-db")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine
            .evaluate_async(
                "await (async () => { const request = indexedDB.open('content', 1); request.onupgradeneeded = event => { const store = event.target.result.createObjectStore('records'); store.createIndex('byStatus', 'status'); }; const db = await new Promise((resolve, reject) => { request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); const tx = db.transaction('records', 'readwrite'); tx.objectStore('records').put({ ready: true, status: 'ready', buffer: new Uint8Array([3, 5, 8]).buffer, bytes: new Uint16Array([258, 513]) }, 'status'); await new Promise((resolve, reject) => { tx.oncomplete = resolve; tx.onerror = () => reject(tx.error); }); const records = db.transaction('records', 'readonly').objectStore('records'); const read = records.index('byStatus').get('ready'); return await new Promise((resolve, reject) => { read.onsuccess = () => { const value = read.result; resolve({ version: db.version, stores: records.indexNames, value: { ready: value.ready, status: value.status }, buffer: Array.from(new Uint8Array(value.buffer)), typedArray: Array.from(value.bytes) }); }; read.onerror = () => reject(read.error); }); })()",
            )
            .await
            .unwrap(),
        serde_json::json!({
            "version": 1,
            "stores": ["byStatus"],
            "value": {"ready": true, "status": "ready"},
            "buffer": [3, 5, 8],
            "typedArray": [258, 513],
        })
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();

    let profile = fs::read_to_string(&profile_path).unwrap();
    assert!(profile.contains("indexed_db"));
    assert!(profile.contains("status"));
    for suffix in ["", "lock", "events", "readers"] {
        let path = if suffix.is_empty() {
            profile_path.clone()
        } else {
            profile_path.with_extension(suffix)
        };
        let _ = fs::remove_file(path);
    }
}

#[tokio::test]
async fn native_content_process_indexed_db_journal_merges_live_workers() {
    let _guard = native_content_process_test_lock().lock().await;
    let profile_path = std::env::temp_dir().join(format!(
        "glass-native-indexed-db-{}-content-journal.json",
        std::process::id()
    ));
    let observer_path = profile_path
        .parent()
        .unwrap()
        .join(".")
        .join(profile_path.file_name().unwrap());
    let lock_path = profile_path.with_extension("lock");
    let events_path = profile_path.with_extension("events");
    let readers_path = profile_path.with_extension("readers");
    for path in [
        profile_path.clone(),
        lock_path.clone(),
        events_path.clone(),
        readers_path.clone(),
    ] {
        let _ = fs::remove_file(path);
    }
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for _ in 0..2 {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request = read_http_request(&mut stream).await;
            assert_eq!(request.split_whitespace().nth(1), Some("/page"));
            let body = "<p>Content IndexedDB journal</p>";
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });
    let url = format!("http://{address}/page");
    let config = NativeEngineConfig::default()
        .with_storage_path(profile_path.clone())
        .with_initial_url(url.clone());
    let mut first = NativeEngine::new(config.clone()).unwrap();
    let mut second = NativeEngine::new(config.with_storage_path(observer_path)).unwrap();
    first.initialize_async().await.unwrap();
    second.initialize_async().await.unwrap();

    first
        .evaluate_async(
            "await (async () => { const request = indexedDB.open('alpha', 1); request.onupgradeneeded = event => event.target.result.createObjectStore('records'); const db = await new Promise((resolve, reject) => { request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); const write = db.transaction('records', 'readwrite').objectStore('records').put({ owner: 'first' }, 'one'); return await new Promise((resolve, reject) => { write.onsuccess = () => resolve(true); write.onerror = () => reject(write.error); }); })()",
        )
        .await
        .unwrap();
    second
        .evaluate_async(
            "await (async () => { const request = indexedDB.open('beta', 1); request.onupgradeneeded = event => event.target.result.createObjectStore('records'); const db = await new Promise((resolve, reject) => { request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); const write = db.transaction('records', 'readwrite').objectStore('records').put({ owner: 'second' }, 'two'); return await new Promise((resolve, reject) => { write.onsuccess = () => resolve(true); write.onerror = () => reject(write.error); }); })()",
        )
        .await
        .unwrap();
    assert_eq!(
        first
            .evaluate_async(
                "await (async () => { const request = indexedDB.open('beta'); const db = await new Promise((resolve, reject) => { request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); const read = db.transaction('records', 'readonly').objectStore('records').get('two'); return await new Promise((resolve, reject) => { read.onsuccess = () => resolve(read.result); read.onerror = () => reject(read.error); }); })()",
            )
            .await
            .unwrap(),
        serde_json::json!({"owner": "second"})
    );

    second.close_async().await.unwrap();
    first.close_async().await.unwrap();
    server.await.unwrap();
    for path in [profile_path, lock_path, events_path, readers_path] {
        let _ = fs::remove_file(path);
    }
}

#[tokio::test]
async fn native_content_process_synchronizes_document_cookie_with_http_session() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut page_stream, _) = listener.accept().await.unwrap();
        let page_request = read_http_request(&mut page_stream).await;
        assert_eq!(page_request.split_whitespace().nth(1), Some("/page"));
        let page_body = "<p>Cookie owner</p>";
        let page_response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nSet-Cookie: theme=dark; Path=/\r\nSet-Cookie: secret=hidden; HttpOnly; Path=/\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{page_body}",
            page_body.len()
        );
        page_stream
            .write_all(page_response.as_bytes())
            .await
            .unwrap();

        let (mut echo_stream, _) = listener.accept().await.unwrap();
        let echo_request = read_http_request(&mut echo_stream).await;
        assert_eq!(echo_request.split_whitespace().nth(1), Some("/echo"));
        let cookie_header = echo_request.lines().find_map(|line| {
            line.split_once(':').and_then(|(name, value)| {
                name.eq_ignore_ascii_case("cookie").then_some(value.trim())
            })
        });
        assert_eq!(
            cookie_header,
            Some("secret=hidden; session=one; theme=dark")
        );
        let echo_body = "cookie-ok";
        let echo_response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{echo_body}",
            echo_body.len()
        );
        echo_stream
            .write_all(echo_response.as_bytes())
            .await
            .unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine.evaluate_async("document.cookie").await.unwrap(),
        serde_json::json!("theme=dark")
    );
    assert_eq!(
        engine
            .evaluate_async("document.cookie = 'session=one; Path=/'; document.cookie")
            .await
            .unwrap(),
        serde_json::json!("theme=dark; session=one")
    );
    engine
        .evaluate_async("document.cookie = 'page-secret=hidden; HttpOnly; Path=/'; true")
        .await
        .unwrap();
    assert_eq!(
        engine.evaluate_async("document.cookie").await.unwrap(),
        serde_json::json!("session=one; theme=dark")
    );
    engine
        .evaluate_async(
            "fetch('/echo').then(response => response.text()).then(value => { globalThis.cookieFetch = value; });",
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.cookieFetch")
            .await
            .unwrap(),
        serde_json::json!("cookie-ok")
    );
    let cookies = engine.cookies_async().await.unwrap();
    assert!(cookies.iter().any(|cookie| {
        cookie.name == "secret" && cookie.http_only && cookie.domain == address.ip().to_string()
    }));
    engine
        .set_cookies_async(&[Cookie {
            name: "imported".into(),
            value: "yes".into(),
            domain: address.ip().to_string(),
            path: "/".into(),
            expires: 0.0,
            http_only: true,
            secure: false,
            same_site: None,
            is_session: true,
            size: None,
            priority: None,
        }])
        .await
        .unwrap();
    assert!(
        engine
            .cookies_async()
            .await
            .unwrap()
            .iter()
            .any(|cookie| cookie.name == "imported" && cookie.http_only)
    );
    engine.clear_cookies_async().await.unwrap();
    assert!(engine.cookies_async().await.unwrap().is_empty());
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_persists_cookie_profile_through_restart() {
    let _guard = native_content_process_test_lock().lock().await;
    let profile_path = std::env::temp_dir().join(format!(
        "glass-native-web-storage-{}-cookie-restart.json",
        std::process::id()
    ));
    let lock_path = profile_path.with_extension("lock");
    let events_path = profile_path.with_extension("events");
    let _ = fs::remove_file(&profile_path);
    let _ = fs::remove_file(&lock_path);
    let _ = fs::remove_file(&events_path);
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for request_index in 0..2 {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request = read_http_request(&mut stream).await;
            assert_eq!(request.split_whitespace().nth(1), Some("/page"));
            let cookie_header = request.lines().find_map(|line| {
                line.split_once(':').and_then(|(name, value)| {
                    name.eq_ignore_ascii_case("cookie").then_some(value.trim())
                })
            });
            if request_index == 0 {
                assert_eq!(cookie_header, None);
            } else {
                assert_eq!(cookie_header, Some("session=one; theme=dark"));
            }
            let body = "<p>Cookie profile</p>";
            let set_cookie = (request_index == 0)
                .then_some("Set-Cookie: theme=dark; Path=/\r\n")
                .unwrap_or_default();
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n{set_cookie}Content-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });
    let url = format!("http://{address}/page");
    let config = NativeEngineConfig::default()
        .with_storage_path(profile_path.clone())
        .with_initial_url(url);

    {
        let mut engine = NativeEngine::new(config.clone()).unwrap();
        engine.initialize_async().await.unwrap();
        assert_eq!(
            engine.evaluate_async("document.cookie").await.unwrap(),
            serde_json::json!("theme=dark")
        );
        engine
            .evaluate_async("document.cookie = 'session=one; Path=/'; true")
            .await
            .unwrap();
        engine.close_async().await.unwrap();
    }

    let profile: serde_json::Value =
        serde_json::from_slice(&fs::read(&profile_path).unwrap()).unwrap();
    assert_eq!(profile["cookies"].as_array().map(Vec::len), Some(2));

    {
        let mut engine = NativeEngine::new(config).unwrap();
        engine.initialize_async().await.unwrap();
        assert_eq!(
            engine.evaluate_async("document.cookie").await.unwrap(),
            serde_json::json!("session=one; theme=dark")
        );
        engine.close_async().await.unwrap();
    }

    server.await.unwrap();
    let _ = fs::remove_file(profile_path);
    let _ = fs::remove_file(lock_path);
    let _ = fs::remove_file(events_path);
}

#[tokio::test]
async fn native_local_web_storage_persists_through_profile_restart() {
    let profile_path = std::env::temp_dir().join(format!(
        "glass-native-web-storage-{}-local-restart.json",
        std::process::id()
    ));
    let _ = fs::remove_file(&profile_path);
    let config = NativeEngineConfig::default()
        .with_storage_path(profile_path.clone())
        .with_fixture("fixture://persistent-storage", "<p>Persistent storage</p>")
        .unwrap()
        .with_initial_url("fixture://persistent-storage");

    {
        let mut engine = NativeEngine::new(config.clone()).unwrap();
        engine.initialize().unwrap();
        assert_eq!(
            engine
                .evaluate_async(
                    "localStorage.setItem('theme', 'dark'); sessionStorage.setItem('tab', 'one'); true",
                )
                .await
                .unwrap(),
            serde_json::json!(true)
        );
        engine
            .navigate("fixture://persistent-storage#next")
            .unwrap();
        assert_eq!(
            engine
                .evaluate_async(
                    "({ local: localStorage.getItem('theme'), session: sessionStorage.getItem('tab') })",
                )
                .await
                .unwrap(),
            serde_json::json!({"local":"dark","session":"one"})
        );
        engine.close().unwrap();
    }

    let profile = fs::read_to_string(&profile_path).unwrap();
    assert!(profile.contains("theme"));
    assert!(!profile.contains("tab"));

    {
        let mut engine = NativeEngine::new(config).unwrap();
        engine.initialize().unwrap();
        assert_eq!(
            engine
                .evaluate_async(
                    "({ local: localStorage.getItem('theme'), session: sessionStorage.getItem('tab') })",
                )
                .await
                .unwrap(),
            serde_json::json!({"local":"dark","session":null})
        );
        engine.close().unwrap();
    }
    let _ = fs::remove_file(profile_path);
}

#[tokio::test]
async fn native_local_indexed_db_supports_upgrade_crud_and_profile_restart() {
    let profile_path = std::env::temp_dir().join(format!(
        "glass-native-indexed-db-{}-restart.json",
        std::process::id()
    ));
    let _ = fs::remove_file(&profile_path);
    let config = NativeEngineConfig::default()
        .with_storage_path(profile_path.clone())
        .with_fixture("fixture://indexed-db", "<p>IndexedDB owner</p>")
        .unwrap()
        .with_initial_url("fixture://indexed-db");

    {
        let mut engine = NativeEngine::new(config.clone()).unwrap();
        engine.initialize().unwrap();
        assert_eq!(
            engine
                .evaluate_async(
                    "await (async () => { const request = indexedDB.open('notes', 1); request.onupgradeneeded = event => event.target.result.createObjectStore('notes', { keyPath: 'id' }); const db = await new Promise((resolve, reject) => { request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); const write = db.transaction('notes', 'readwrite'); const store = write.objectStore('notes'); const initial = store.put({ id: 'one', title: 'hello', count: 2 }); await new Promise((resolve, reject) => { initial.onsuccess = () => { store.put({ id: 'one', title: 'hello', count: 3 }); write.oncomplete = resolve; }; initial.onerror = () => reject(initial.error); write.onerror = () => reject(write.error); }); const read = db.transaction('notes', 'readonly'); const get = read.objectStore('notes').get('one'); const value = await new Promise((resolve, reject) => { get.onsuccess = () => resolve(get.result); get.onerror = () => reject(get.error); }); return { name: db.name, version: db.version, stores: db.objectStoreNames, value, count: await new Promise((resolve, reject) => { const count = db.transaction('notes', 'readonly').objectStore('notes').count(); count.onsuccess = () => resolve(count.result); count.onerror = () => reject(count.error); }) }; })()",
                )
                .await
                .unwrap(),
            serde_json::json!({
                "name": "notes",
                "version": 1,
                "stores": ["notes"],
                "value": {"id": "one", "title": "hello", "count": 3},
                "count": 1,
            })
        );
        engine.close().unwrap();
    }

    let profile = fs::read_to_string(&profile_path).unwrap();
    assert!(profile.contains("indexed_db"));
    assert!(profile.contains("hello"));

    {
        let mut engine = NativeEngine::new(config).unwrap();
        engine.initialize().unwrap();
        assert_eq!(
            engine
                .evaluate_async(
                    "await (async () => { const request = indexedDB.open('notes'); const db = await new Promise((resolve, reject) => { request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); const read = db.transaction('notes', 'readonly').objectStore('notes').getAll(); return await new Promise((resolve, reject) => { read.onsuccess = () => resolve(read.result); read.onerror = () => reject(read.error); }); })()",
                )
                .await
                .unwrap(),
            serde_json::json!([{"id": "one", "title": "hello", "count": 3}])
        );
        engine.close().unwrap();
    }
    for suffix in ["", "lock", "events", "readers"] {
        let path = if suffix.is_empty() {
            profile_path.clone()
        } else {
            profile_path.with_extension(suffix)
        };
        let _ = fs::remove_file(path);
    }
}

#[tokio::test]
async fn native_local_indexed_db_supports_indexes_key_ranges_and_cursors() {
    let profile_path = std::env::temp_dir().join(format!(
        "glass-native-indexed-db-{}-indexes.json",
        std::process::id()
    ));
    let _ = fs::remove_file(&profile_path);
    let config = NativeEngineConfig::default()
        .with_storage_path(profile_path.clone())
        .with_fixture("fixture://indexed-db-indexes", "<p>IndexedDB indexes</p>")
        .unwrap()
        .with_initial_url("fixture://indexed-db-indexes");

    {
        let mut engine = NativeEngine::new(config.clone()).unwrap();
        engine.initialize().unwrap();
        assert_eq!(
            engine
                .evaluate_async(
                    "await (async () => { const request = indexedDB.open('catalog', 1); request.onupgradeneeded = event => { const store = event.target.result.createObjectStore('records', { keyPath: 'id' }); store.createIndex('byTag', 'tags', { multiEntry: true }); store.createIndex('byType', 'type'); store.createIndex('bySku', 'sku', { unique: true }); }; const db = await new Promise((resolve, reject) => { request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); const write = db.transaction('records', 'readwrite'); const store = write.objectStore('records'); for (const record of [{ id: 'c', type: 'b', sku: 'sku-c', tags: ['green', 'blue'] }, { id: 'a', type: 'a', sku: 'sku-a', tags: ['green'] }, { id: 'b', type: 'b', sku: 'sku-b', tags: ['blue'] }]) store.put(record); await new Promise((resolve, reject) => { write.oncomplete = resolve; write.onerror = () => reject(write.error); }); const read = db.transaction('records', 'readonly'); const records = read.objectStore('records'); const byType = records.index('byType'); const byTag = records.index('byTag'); const requestValue = request => new Promise((resolve, reject) => { request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); const values = await requestValue(byType.getAll(IDBKeyRange.bound('a', 'b'))); const green = await requestValue(byTag.getAll('green')); const firstGreenKey = await requestValue(byTag.getKey('green')); const count = await requestValue(byType.count(IDBKeyRange.lowerBound('b'))); const cursorKeys = await new Promise((resolve, reject) => { const cursorRequest = byType.openCursor(); const seen = []; cursorRequest.onsuccess = () => { const cursor = cursorRequest.result; if (!cursor) return resolve(seen); seen.push(cursor.primaryKey); if (seen.length === 1) cursor.advance(2); else cursor.continue(); }; cursorRequest.onerror = () => reject(cursorRequest.error); }); const keyCursorKeys = await new Promise((resolve, reject) => { const cursorRequest = records.openKeyCursor(IDBKeyRange.lowerBound('b'), 'prev'); const seen = []; cursorRequest.onsuccess = () => { const cursor = cursorRequest.result; if (!cursor) return resolve(seen); seen.push(cursor.key); cursor.continue(); }; cursorRequest.onerror = () => reject(cursorRequest.error); }); const conflictTx = db.transaction('records', 'readwrite'); const conflict = conflictTx.objectStore('records').put({ id: 'd', type: 'd', sku: 'sku-a', tags: [] }); const uniqueError = await new Promise(resolve => { conflict.onsuccess = () => resolve('none'); conflict.onerror = () => resolve(conflict.error.name); }); await new Promise((resolve, reject) => { const mutation = db.transaction('records', 'readwrite'); const mutationStore = mutation.objectStore('records'); const mutationCursor = mutationStore.index('byType').openCursor(IDBKeyRange.only('b')); mutation.oncomplete = resolve; mutation.onerror = () => reject(mutation.error); mutationCursor.onerror = () => reject(mutationCursor.error); mutationCursor.onsuccess = () => { const cursor = mutationCursor.result; if (!cursor) return; if (cursor.primaryKey === 'b') { const update = cursor.update({ id: 'b', type: 'b', sku: 'sku-b', tags: ['updated'] }); update.onerror = () => reject(update.error); update.onsuccess = () => cursor.continue(); } else { const remove = cursor.delete(); remove.onerror = () => reject(remove.error); remove.onsuccess = () => cursor.continue(); } }; }); const updated = await requestValue(db.transaction('records', 'readonly').objectStore('records').index('byTag').get('updated')); const remaining = await requestValue(db.transaction('records', 'readonly').objectStore('records').index('byType').getAll('b')); return { indexNames: records.indexNames, values: values.map(value => value.id), green: green.map(value => value.id), firstGreenKey, count, cursorKeys, keyCursorKeys, uniqueError, updated: updated.id, remaining: remaining.map(value => value.id) }; })()",
                )
                .await
                .unwrap(),
            serde_json::json!({
                "indexNames": ["bySku", "byTag", "byType"],
                "values": ["a", "b", "c"],
                "green": ["a", "c"],
                "firstGreenKey": "a",
                "count": 2,
                "cursorKeys": ["a", "c"],
                "keyCursorKeys": ["c", "b"],
                "uniqueError": "ConstraintError",
                "updated": "b",
                "remaining": ["b"],
            })
        );
        engine.close().unwrap();
    }

    {
        let mut engine = NativeEngine::new(config).unwrap();
        engine.initialize().unwrap();
        assert_eq!(
            engine
                .evaluate_async(
                    "await (async () => { const request = indexedDB.open('catalog'); const db = await new Promise((resolve, reject) => { request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); const read = db.transaction('records', 'readonly').objectStore('records').index('bySku').get('sku-b'); return await new Promise((resolve, reject) => { read.onsuccess = () => resolve(read.result); read.onerror = () => reject(read.error); }); })()",
                )
                .await
                .unwrap(),
            serde_json::json!({"id": "b", "type": "b", "sku": "sku-b", "tags": ["updated"]})
        );
        engine.close().unwrap();
    }
    for suffix in ["", "lock", "events", "readers"] {
        let path = if suffix.is_empty() {
            profile_path.clone()
        } else {
            profile_path.with_extension(suffix)
        };
        let _ = fs::remove_file(path);
    }
}

