#[tokio::test]
async fn native_content_process_drives_websocket_text_binary_and_close_events() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/page"));
        let body = format!(
            "<input id='result' value='pending'><script>globalThis.pageScriptStatus = 'before'; try {{ globalThis.pageSocket = new WebSocket('ws://{address}/socket'); globalThis.pageScriptStatus = 'after'; }} catch (error) {{ globalThis.pageScriptStatus = String(error); }}</script>"
        );
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();

        let (stream, _) = listener.accept().await.unwrap();
        let mut websocket = accept_async(stream).await.unwrap();
        websocket
            .send(Message::Ping(b"keepalive".to_vec().into()))
            .await
            .unwrap();
        websocket
            .send(Message::Text("server-text".into()))
            .await
            .unwrap();
        websocket
            .send(Message::Binary(vec![7_u8, 8, 255].into()))
            .await
            .unwrap();
        let mut received = Vec::new();
        let mut pong_received = false;
        while received.len() < 2 || !pong_received {
            match tokio::time::timeout(Duration::from_secs(2), websocket.next())
                .await
                .unwrap()
                .unwrap()
                .unwrap()
            {
                Message::Text(value) => received.push(("text", value.to_string().into_bytes())),
                Message::Binary(value) => received.push(("binary", value.to_vec())),
                Message::Close(_) => break,
                Message::Pong(value) => {
                    assert_eq!(value.as_ref(), b"keepalive");
                    pong_received = true;
                }
                Message::Ping(_) => {}
                _ => {}
            }
        }
        assert_eq!(
            received,
            vec![("text", b"client-text".to_vec()), ("binary", vec![1, 2, 3])]
        );
        assert!(pong_received);
        let _ = tokio::time::timeout(Duration::from_secs(2), websocket.next()).await;
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine
            .evaluate_async("[globalThis.pageScriptStatus, typeof globalThis.pageSocket]")
            .await
            .unwrap(),
        serde_json::json!(["after", "object"])
    );
    assert_eq!(
        engine
            .evaluate_async(&format!(
                "await new Promise((resolve, reject) => {{ const socket = globalThis.pageSocket; socket.binaryType = 'arraybuffer'; socket.onopen = () => {{ socket.send('client-text'); socket.send(new Uint8Array([1, 2, 3])); }}; const messages = []; socket.onmessage = event => {{ if (typeof event.data === 'string') messages.push(event.data); else messages.push(Array.from(new Uint8Array(event.data)).join(',')); if (messages.length === 2) {{ document.getElementById('result').value = messages.join('|'); socket.close(1000, 'done'); resolve(messages.join('|')); }} }}; socket.onerror = () => reject(new Error('websocket failed')); }})"
            ))
            .await
            .unwrap(),
        serde_json::json!("server-text|7,8,255")
    );
    assert_eq!(
        engine
            .evaluate_async("document.getElementById('result').value")
            .await
            .unwrap(),
        serde_json::json!("server-text|7,8,255")
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_drives_event_source_named_multiline_events() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/page"));
        let body = "<body></body><script>globalThis.pageCookie = document.cookie; globalThis.pageSource = new EventSource('/events');</script>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nSet-Cookie: session=page; Path=/\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();

        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().next(), Some("GET"));
        assert_eq!(request.split_whitespace().nth(1), Some("/events"));
        assert!(request.lines().any(|line| {
            line.split_once(':').is_some_and(|(name, value)| {
                name.eq_ignore_ascii_case("accept") && value.trim() == "text/event-stream"
            })
        }));
        assert!(request.lines().any(|line| {
            line.split_once(':').is_some_and(|(name, value)| {
                name.eq_ignore_ascii_case("cookie")
                    && value
                        .split(';')
                        .any(|cookie| cookie.trim() == "session=page")
            })
        }));
        let first = b"retry: 5\rid: 42\revent: greeting\rdata: hello\r";
        let second = b"\ndata: world\r\r";
        stream
            .write_all(
                b"HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nCache-Control: no-cache\r\nSet-Cookie: sse=connected; Path=/\r\nTransfer-Encoding: chunked\r\nConnection: keep-alive\r\n\r\n",
            )
            .await
            .unwrap();
        stream
            .write_all(format!("{:X}\r\n", first.len()).as_bytes())
            .await
            .unwrap();
        stream.write_all(first).await.unwrap();
        stream.write_all(b"\r\n").await.unwrap();
        stream
            .write_all(format!("{:X}\r\n", second.len()).as_bytes())
            .await
            .unwrap();
        stream.write_all(second).await.unwrap();
        stream.write_all(b"\r\n").await.unwrap();
        let mut close_probe = [0_u8; 1];
        let _ =
            tokio::time::timeout(Duration::from_millis(100), stream.read(&mut close_probe)).await;

        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/check"));
        assert!(request.lines().any(|line| {
            line.split_once(':').is_some_and(|(name, value)| {
                name.eq_ignore_ascii_case("cookie")
                    && value
                        .split(';')
                        .any(|cookie| cookie.trim() == "sse=connected")
            })
        }));
        let body = "cookie-ok";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine
            .evaluate_async(
                "await new Promise((resolve, reject) => { const source = globalThis.pageSource; source.addEventListener('greeting', event => { document.body.setAttribute('data-event', event.type); document.body.setAttribute('data-last-id', event.lastEventId); document.body.setAttribute('data-message', event.data); source.close(); resolve([event.type, event.data, event.lastEventId, source.readyState]); }); source.onerror = event => reject(new Error('event source failed: ' + event.message)); })",
            )
            .await
            .unwrap(),
        serde_json::json!(["greeting", "hello\nworld", "42", 2])
    );
    assert_eq!(
        engine
            .evaluate_async("[document.body.getAttribute('data-event'), document.body.getAttribute('data-last-id'), document.body.getAttribute('data-message')]")
            .await
            .unwrap(),
        serde_json::json!(["greeting", "42", "hello\nworld"])
    );
    assert_eq!(
        engine
            .evaluate_async("await fetch('/check').then(response => response.text())")
            .await
            .unwrap(),
        serde_json::json!("cookie-ok")
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_streams_fetch_response_body_incrementally() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/page"));
        let body = "<body>Fetch stream owner</body>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();

        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/stream"));
        stream
            .write_all(
                b"HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n",
            )
            .await
            .unwrap();
        let first = [1_u8, 2, 3];
        stream
            .write_all(format!("{:X}\r\n", first.len()).as_bytes())
            .await
            .unwrap();
        stream.write_all(&first).await.unwrap();
        stream.write_all(b"\r\n").await.unwrap();
        tokio::time::sleep(Duration::from_millis(25)).await;
        let second = [4_u8, 5];
        stream
            .write_all(format!("{:X}\r\n", second.len()).as_bytes())
            .await
            .unwrap();
        stream.write_all(&second).await.unwrap();
        stream.write_all(b"\r\n0\r\n\r\n").await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine
            .evaluate_async(
                "await (async () => { const response = await fetch('/stream'); const reader = response.body.getReader(); const first = await reader.read(); const second = await reader.read(); const end = await reader.read(); return [response.status, response.body instanceof ReadableStream, Array.from(first.value), Array.from(second.value), end.done]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([200, true, [1, 2, 3], [4, 5], true])
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_cancels_fetch_response_stream_transport() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let (cancelled_sender, cancelled_receiver) = oneshot::channel();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/page"));
        let body = "<body>Fetch cancellation owner</body>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();

        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/stream-cancel"));
        stream
            .write_all(
                b"HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n",
            )
            .await
            .unwrap();
        stream.write_all(b"5\r\nfirst\r\n").await.unwrap();
        let mut probe = [0_u8; 1];
        let closed = tokio::time::timeout(Duration::from_secs(3), stream.read(&mut probe))
            .await
            .unwrap()
            .unwrap();
        assert_eq!(closed, 0, "cancelled response body remained connected");
        cancelled_sender.send(()).unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine
            .evaluate_async(
                "await (async () => { const response = await fetch('/stream-cancel'); const reader = response.body.getReader(); const first = await reader.read(); await reader.cancel(); const after = await reader.read(); reader.releaseLock(); return [Array.from(first.value), first.done, after.done, response.body.locked]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([[102, 105, 114, 115, 116], false, true, false])
    );
    tokio::time::timeout(Duration::from_secs(3), cancelled_receiver)
        .await
        .unwrap()
        .unwrap();
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_tracks_fetch_body_disturbance_and_clone_ownership() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for expected_path in ["/page", "/body", "/body"] {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request = read_http_request(&mut stream).await;
            assert_eq!(request.split_whitespace().nth(1), Some(expected_path));
            let (content_type, body) = if expected_path == "/page" {
                ("text/html", "<body>Fetch body owner</body>")
            } else {
                ("text/plain", "body-used")
            };
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine
            .evaluate_async(
                "await (async () => { const response = await fetch('/body'); const clone = response.clone(); const initial = [response.bodyUsed, clone.bodyUsed]; const text = await response.text(); const responseAfter = [response.bodyUsed, await response.text().then(() => 'readable', error => error.name), (() => { try { response.clone(); return 'cloneable'; } catch (error) { return error.name; } })()]; const cloneText = await clone.text(); const cloneAfter = [clone.bodyUsed, await clone.text().then(() => 'readable', error => error.name), (() => { try { clone.clone(); return 'cloneable'; } catch (error) { return error.name; } })()]; const locked = await fetch('/body'); const reader = locked.body.getReader(); const lockState = [locked.bodyUsed, (() => { try { locked.clone(); return 'cloneable'; } catch (error) { return error.name; } })()]; const first = await reader.read(); const disturbed = locked.bodyUsed; await reader.cancel(); reader.releaseLock(); const canceled = [locked.bodyUsed, (() => { try { locked.clone(); return 'cloneable'; } catch (error) { return error.name; } })()]; return { initial, text, responseAfter, cloneText, cloneAfter, lockState, first: [Array.from(first.value), first.done], disturbed, canceled }; })()",
            )
            .await
            .unwrap(),
        serde_json::json!({
            "initial": [false, false],
            "text": "body-used",
            "responseAfter": [true, "TypeError", "TypeError"],
            "cloneText": "body-used",
            "cloneAfter": [true, "TypeError", "TypeError"],
            "lockState": [false, "TypeError"],
            "first": [[98, 111, 100, 121, 45, 117, 115, 101, 100], false],
            "disturbed": true,
            "canceled": [true, "TypeError"]
        })
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

