#[tokio::test]
async fn native_content_process_tees_fetch_streams_until_all_readers_cancel() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let (closed_sender, mut closed_receiver) = oneshot::channel();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/page"));
        let body = "<body>Fetch tee owner</body>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();

        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/tee"));
        stream
            .write_all(
                b"HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n",
            )
            .await
            .unwrap();
        stream.write_all(b"3\r\ntee\r\n").await.unwrap();
        let mut probe = [0_u8; 1];
        let closed = stream.read(&mut probe).await.unwrap();
        assert_eq!(
            closed, 0,
            "tee transport closed before all readers canceled"
        );
        closed_sender.send(()).unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine
            .evaluate_async(
                "await (async () => { const response = await fetch('/tee'); const clone = response.clone(); const left = response.body.getReader(); const right = clone.body.getReader(); const leftFirst = await left.read(); const rightFirst = await right.read(); await left.cancel(); await right.cancel(); left.releaseLock(); right.releaseLock(); return [Array.from(leftFirst.value), leftFirst.done, Array.from(rightFirst.value), rightFirst.done, response.bodyUsed, clone.bodyUsed]; })()",
            )
            .await
            .unwrap(),
        serde_json::json!([[116, 101, 101], false, [116, 101, 101], false, true, true])
    );
    tokio::time::timeout(Duration::from_secs(3), &mut closed_receiver)
        .await
        .unwrap()
        .unwrap();
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_exposes_bounded_same_origin_post_fetch() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for expected_path in ["/page", "/submit"] {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request = read_http_request(&mut stream).await;
            assert_eq!(request.split_whitespace().nth(1), Some(expected_path));
            if expected_path == "/submit" {
                assert_eq!(request.split_whitespace().next(), Some("POST"));
                assert!(request.lines().any(|line| {
                    line.split_once(':').is_some_and(|(name, value)| {
                        name.eq_ignore_ascii_case("content-type")
                            && value.trim() == "application/json"
                    })
                }));
                let body = request
                    .split_once("\r\n\r\n")
                    .map(|(_, body)| body)
                    .unwrap_or_default();
                assert_eq!(body, r#"{"name":"glass"}"#);
            }
            let (content_type, body) = if expected_path == "/page" {
                ("text/html", "<p>Fetch owner</p>")
            } else {
                ("application/json", "{\"value\":\"posted\"}")
            };
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            "fetch('/submit', { method: 'POST', body: '{\"name\":\"glass\"}', headers: { 'Content-Type': 'application/json' } }).then(response => response.json()).then(data => { globalThis.postFetchValue = data.value; });",
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.postFetchValue")
            .await
            .unwrap(),
        serde_json::json!("posted")
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_exposes_bounded_xhr_fetch_bridge() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for expected_path in ["/page", "/xhr", "/binary", "/xhr-binary", "/xhr-blob"] {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request_bytes = read_http_request_bytes(&mut stream).await;
            let request = String::from_utf8_lossy(&request_bytes);
            assert_eq!(request.split_whitespace().nth(1), Some(expected_path));
            if expected_path == "/xhr" {
                assert_eq!(request.split_whitespace().next(), Some("POST"));
                assert!(request.lines().any(|line| {
                    line.split_once(':').is_some_and(|(name, value)| {
                        name.eq_ignore_ascii_case("content-type")
                            && value.trim() == "application/json"
                    })
                }));
                let body = request
                    .split_once("\r\n\r\n")
                    .map(|(_, body)| body)
                    .unwrap_or_default();
                assert_eq!(body, r#"{"name":"glass"}"#);
            }
            if expected_path == "/xhr-binary" {
                assert_eq!(request.split_whitespace().next(), Some("POST"));
                assert!(request.lines().any(|line| {
                    line.split_once(':').is_some_and(|(name, value)| {
                        name.eq_ignore_ascii_case("content-type")
                            && value.trim() == "application/octet-stream"
                    })
                }));
                let header_end = request_bytes
                    .windows(4)
                    .position(|window| window == b"\r\n\r\n")
                    .unwrap()
                    + 4;
                assert_eq!(&request_bytes[header_end..], [0_u8, 0xff, 0x80, b'A']);
            }
            if matches!(expected_path, "/binary" | "/xhr-binary" | "/xhr-blob") {
                let body = [0_u8, 0xff, 0x80, b'A'];
                let response = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                    body.len()
                );
                stream.write_all(response.as_bytes()).await.unwrap();
                stream.write_all(&body).await.unwrap();
                continue;
            }
            let (content_type, body) = if expected_path == "/page" {
                ("text/html", "<p>XHR owner</p>")
            } else {
                ("text/plain", "xhr-response")
            };
            let extra_headers = if expected_path == "/xhr" {
                "X-Glass-Response: one\r\nX-Glass-Response: two\r\n"
            } else {
                ""
            };
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\n{extra_headers}Content-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            r#"(() => {
                const xhr = new XMLHttpRequest();
                xhr.open('POST', '/xhr');
                xhr.setRequestHeader('Content-Type', 'application/json');
                xhr.onload = async () => {
                    globalThis.xhrResult = [xhr.status, xhr.responseText, xhr.responseURL, xhr.getResponseHeader('content-type'), xhr.getResponseHeader('x-glass-response'), xhr.getAllResponseHeaders()];
                    const binaryResponse = await fetch('/binary');
                    const binaryBlob = await binaryResponse.blob();
                    const binaryXhr = new XMLHttpRequest();
                    binaryXhr.open('POST', '/xhr-binary');
                    binaryXhr.responseType = 'arraybuffer';
                    binaryXhr.setRequestHeader('Content-Type', 'application/octet-stream');
                    binaryXhr.onload = async () => {
                        globalThis.xhrBinaryResult = [binaryXhr.status, binaryXhr.response instanceof ArrayBuffer, Array.from(new Uint8Array(binaryXhr.response)), binaryXhr.responseText, binaryXhr.responseURL];
                        const blobXhr = new XMLHttpRequest();
                        blobXhr.open('GET', '/xhr-blob');
                        blobXhr.responseType = 'blob';
                        blobXhr.onload = async () => {
                            globalThis.xhrBlobResult = [blobXhr.status, blobXhr.response instanceof Blob, blobXhr.response.size, Array.from(await blobXhr.response.bytes()), blobXhr.responseText, blobXhr.responseURL];
                        };
                        blobXhr.send();
                    };
                    binaryXhr.send(binaryBlob);
                };
                xhr.send(new Blob(['{"name":"glass"}'], { type: 'application/json' }));
            })()"#,
        )
        .await
        .unwrap();
    assert_eq!(
        engine.evaluate_async("globalThis.xhrResult").await.unwrap(),
        serde_json::json!([
            200,
            "xhr-response",
            format!("http://{address}/xhr"),
            "text/plain",
            "one, two",
            "content-type: text/plain\r\nx-glass-response: one, two\r\ncontent-length: 12\r\nconnection: close\r\n"
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.xhrBinaryResult")
            .await
            .unwrap(),
        serde_json::json!([
            200,
            true,
            [0, 255, 128, 65],
            "",
            format!("http://{address}/xhr-binary")
        ])
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.xhrBlobResult")
            .await
            .unwrap(),
        serde_json::json!([
            200,
            true,
            4,
            [0, 255, 128, 65],
            "",
            format!("http://{address}/xhr-blob")
        ])
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_xhr_abort_is_observable_and_ignores_late_callbacks() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let request = read_http_request(&mut stream).await;
        assert_eq!(request.split_whitespace().nth(1), Some("/page"));
        let body = "<p>XHR abort</p>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });
    let config = NativeEngineConfig::default().with_initial_url(format!("http://{address}/page"));
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            r#"(() => {
                const xhr = new XMLHttpRequest();
                const events = [];
                xhr.onreadystatechange = () => events.push(`state:${xhr.readyState}`);
                xhr.onload = () => events.push('load');
                xhr.onerror = () => events.push('error');
                xhr.onabort = event => events.push(`${event.type}:${xhr.readyState}`);
                xhr.open('GET', 'data:text/plain,never');
                xhr.send();
                xhr.abort();
                globalThis.xhrAbortResult = [xhr.readyState, xhr.status, xhr.responseText, xhr.responseURL, events];
            })()"#,
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.xhrAbortResult")
            .await
            .unwrap(),
        serde_json::json!([0, 0, "", "", ["state:1", "state:0", "abort:0"]])
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_xhr_timeout_is_bounded_and_observable() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for expected_path in ["/page", "/slow"] {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request = read_http_request(&mut stream).await;
            assert_eq!(request.split_whitespace().nth(1), Some(expected_path));
            if expected_path == "/slow" {
                tokio::time::sleep(Duration::from_millis(100)).await;
            }
            let body = if expected_path == "/page" {
                "<p>XHR timeout</p>"
            } else {
                "late-response"
            };
            let content_type = if expected_path == "/page" {
                "text/html"
            } else {
                "text/plain"
            };
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len(),
            );
            let _ = stream.write_all(response.as_bytes()).await;
        }
    });
    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            r#"(() => {
                const xhr = new XMLHttpRequest();
                const events = [];
                xhr.onreadystatechange = () => events.push(`state:${xhr.readyState}`);
                xhr.onerror = () => events.push('error');
                xhr.ontimeout = event => {
                    events.push(`${event.type}:${xhr.readyState}`);
                    globalThis.xhrTimeoutResult = [xhr.timeout, xhr.readyState, xhr.status, xhr.responseText, xhr.responseURL, events];
                };
                xhr.open('GET', '/slow');
                xhr.timeout = 20;
                xhr.send();
            })()"#,
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.xhrTimeoutResult")
            .await
            .unwrap(),
        serde_json::json!([20, 4, 0, "", "", ["state:1", "state:4", "timeout:4"]])
    );
    assert_eq!(
        engine
            .evaluate_async(
                "(() => { try { const xhr = new XMLHttpRequest(); xhr.timeout = 4001; return 'accepted'; } catch (error) { return [error.name, error.message]; } })()",
            )
            .await
            .unwrap(),
        serde_json::json!(["RangeError", "native XMLHttpRequest timeout is outside the bounded range"])
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_fetches_bounded_text_form_data() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for expected_path in ["/page", "/formdata"] {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request = read_http_request(&mut stream).await;
            assert_eq!(request.split_whitespace().nth(1), Some(expected_path));
            if expected_path == "/formdata" {
                assert_eq!(request.split_whitespace().next(), Some("POST"));
                let content_type = request.lines().find_map(|line| {
                    line.split_once(':').and_then(|(name, value)| {
                        name.eq_ignore_ascii_case("content-type")
                            .then_some(value.trim().to_owned())
                    })
                });
                assert!(content_type.is_some_and(|value| {
                    value.starts_with("multipart/form-data; boundary=----GlassNativeForm")
                }));
                let body = request
                    .split_once("\r\n\r\n")
                    .map(|(_, body)| body)
                    .unwrap_or_default();
                assert!(
                    body.contains("Content-Disposition: form-data; name=\"name\"\r\n\r\nGlass\r\n"),
                    "unexpected FormData body: {body:?}"
                );
                assert!(
                    body.contains("Content-Disposition: form-data; name=\"tag\"\r\n\r\nengine\r\n"),
                    "unexpected FormData body: {body:?}"
                );
            }
            let (content_type, body) = if expected_path == "/page" {
                ("text/html", "<p>FormData owner</p>")
            } else {
                ("text/plain", "formdata-accepted")
            };
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            r#"(() => {
                const formData = new FormData();
                formData.append('name', 'Glass');
                formData.append('tag', 'old');
                formData.set('tag', 'engine');
                const iterator = formData.entries();
                const first = iterator.next();
                const second = iterator.next();
                const done = iterator.next();
                const visited = [];
                formData.forEach((value, name) => visited.push(name + '=' + value));
                globalThis.formDataIterator = [
                    iterator[Symbol.iterator]() === iterator,
                    first.value,
                    second.value,
                    done.done,
                    Array.from(formData.keys()),
                    Array.from(formData.values()),
                    Array.from(formData).map(entry => entry.join('=')),
                    visited,
                ];
                fetch('/formdata', { method: 'POST', body: formData })
                    .then(response => response.text())
                    .then(text => { globalThis.formDataResponse = text; });
            })()"#,
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.formDataResponse")
            .await
            .unwrap(),
        serde_json::json!("formdata-accepted")
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.formDataIterator")
            .await
            .unwrap(),
        serde_json::json!([
            true,
            ["name", "Glass"],
            ["tag", "engine"],
            true,
            ["name", "tag"],
            ["Glass", "engine"],
            ["name=Glass", "tag=engine"],
            ["name=Glass", "tag=engine"]
        ])
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_fetches_bounded_url_search_params() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for expected_path in ["/page", "/params"] {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request = read_http_request(&mut stream).await;
            assert_eq!(request.split_whitespace().nth(1), Some(expected_path));
            if expected_path == "/params" {
                assert_eq!(request.split_whitespace().next(), Some("POST"));
                assert!(request.lines().any(|line| {
                    line.split_once(':').is_some_and(|(name, value)| {
                        name.eq_ignore_ascii_case("content-type")
                            && value.trim() == "application/x-www-form-urlencoded;charset=UTF-8"
                    })
                }));
                let body = request
                    .split_once("\r\n\r\n")
                    .map(|(_, body)| body)
                    .unwrap_or_default();
                assert_eq!(body, "name=Glass&tag=engine");
            }
            let (content_type, body) = if expected_path == "/page" {
                ("text/html", "<p>URLSearchParams owner</p>")
            } else {
                ("text/plain", "params-accepted")
            };
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    engine
        .evaluate_async(
            r#"(() => {
                const params = new URLSearchParams();
                params.append('name', 'Glass');
                params.append('tag', 'old');
                params.set('tag', 'engine');
                const api = new URLSearchParams([['z', 'last'], ['a', 'first'], ['a', 'second']]);
                api.sort();
                const visited = [];
                api.forEach((value, name) => visited.push(name + '=' + value));
                const mapIterable = new URLSearchParams(new Map([['b', 'two'], ['a', 'one']]));
                const setIterable = new URLSearchParams(new Set([['x', 'one'], ['y', 'two']]));
                globalThis.paramsApi = { size: api.size, entries: Array.from(api.entries()), keys: Array.from(api.keys()), values: Array.from(api.values()), visited, record: new URLSearchParams({ b: 'two', a: 'one' }).toString(), mapIterable: mapIterable.toString(), setIterable: setIterable.toString() };
                fetch('/params', { method: 'POST', body: params })
                    .then(response => response.text())
                    .then(text => { globalThis.paramsResponse = text; });
            })()"#,
        )
        .await
        .unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.paramsResponse")
            .await
            .unwrap(),
        serde_json::json!("params-accepted")
    );
    assert_eq!(
        engine.evaluate_async("globalThis.paramsApi").await.unwrap(),
        serde_json::json!({
            "size": 3,
            "entries": [["a", "first"], ["a", "second"], ["z", "last"]],
            "keys": ["a", "a", "z"],
            "values": ["first", "second", "last"],
            "visited": ["a=first", "a=second", "z=last"],
            "record": "b=two&a=one",
            "mapIterable": "b=two&a=one",
            "setIterable": "x=one&y=two",
        })
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}
